CREATE OR REPLACE FUNCTION mcp.mcp_backfill_session_customers_from_route(
  p_session_id text,
  p_only_if_empty boolean DEFAULT true
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $function$
DECLARE
  v_session mcp.mcp_route_sessions%rowtype;
  v_before_count integer := 0;
  v_active_count integer := 0;
  v_inserted_count integer := 0;
BEGIN
  IF NULLIF(btrim(COALESCE(p_session_id, '')), '') IS NULL THEN
    RAISE EXCEPTION 'session_id_required' USING ERRCODE = '23514';
  END IF;

  SELECT * INTO v_session
  FROM mcp.mcp_route_sessions
  WHERE id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'session_not_found' USING ERRCODE = '23503';
  END IF;

  SELECT count(*)::integer INTO v_before_count
  FROM mcp.mcp_session_customers
  WHERE session_id = v_session.id;

  SELECT count(*)::integer INTO v_active_count
  FROM mcp.mcp_route_customers
  WHERE route_id = v_session.route_id
    AND COALESCE(active, true) IS true;

  IF COALESCE(p_only_if_empty, true) AND v_before_count > 0 THEN
    RETURN jsonb_build_object(
      'sessionId', v_session.id,
      'routeId', v_session.route_id,
      'beforeCount', v_before_count,
      'insertedCount', 0,
      'activeRouteCustomers', v_active_count,
      'skipped', 'existing_session_snapshot_frozen'
    );
  END IF;

  INSERT INTO mcp.mcp_session_customers (
    id, installation_id, session_id, route_id, route_customer_id,
    customer_id, customer_name, phone, area, address, sort_order,
    source, planned_status, visit_status, note, raw_payload, created_at, updated_at
  )
  SELECT
    'msc_' || replace(gen_random_uuid()::text, '-', ''),
    COALESCE(route_customer.installation_id, v_session.installation_id),
    v_session.id,
    v_session.route_id,
    route_customer.id,
    route_customer.customer_id,
    route_customer.customer_name,
    route_customer.phone,
    COALESCE(route_customer.area, v_session.area),
    route_customer.address,
    route_customer.sort_order,
    'master',
    'planned',
    'pending',
    route_customer.note,
    jsonb_build_object(
      'source', 'mcp_backfill_session_customers_from_route',
      'route_customer_id', route_customer.id
    ),
    now(),
    now()
  FROM mcp.mcp_route_customers route_customer
  WHERE route_customer.route_id = v_session.route_id
    AND COALESCE(route_customer.active, true) IS true
    AND NOT EXISTS (
      SELECT 1
      FROM mcp.mcp_session_customers session_customer
      WHERE session_customer.session_id = v_session.id
        AND session_customer.route_customer_id = route_customer.id
    )
  ORDER BY route_customer.sort_order, route_customer.id
  ON CONFLICT (session_id, route_customer_id) WHERE route_customer_id IS NOT NULL DO NOTHING;

  GET DIAGNOSTICS v_inserted_count = ROW_COUNT;

  RETURN jsonb_build_object(
    'sessionId', v_session.id,
    'routeId', v_session.route_id,
    'beforeCount', v_before_count,
    'insertedCount', v_inserted_count,
    'activeRouteCustomers', v_active_count
  );
END;
$function$;

-- Source: 20260704_mcp_standardize_session_counters.sql
create or replace function mcp.mcp_recalc_session_customer_followup_count(p_session_customer_id text)
returns void
language plpgsql
set search_path = public
as $$
begin
  if p_session_customer_id is null then
    return;
  end if;

  update mcp.mcp_session_customers sc
     set followup_count = (
           select count(*)::integer
             from mcp.mcp_followups f
            where f.session_customer_id = p_session_customer_id
              and coalesce(f.status, 'open') = 'open'
         ),
         updated_at = now()
   where sc.id = p_session_customer_id;
end;
$$;

-- Source: 20260704_mcp_standardize_session_counters.sql
create or replace function mcp.mcp_recalc_route_session_counters(p_session_id text)
returns void
language plpgsql
set search_path = public
as $$
begin
  if p_session_id is null then
    return;
  end if;

  update mcp.mcp_route_sessions s
     set planned_customers = (
           select count(*)::integer
             from mcp.mcp_session_customers sc
            where sc.session_id = p_session_id
         ),
         visited_customers = (
           select count(*)::integer
             from mcp.mcp_session_customers sc
            where sc.session_id = p_session_id
              and sc.visit_status = 'visited'
         ),
         order_count = (
           select count(*)::integer
             from mcp.mcp_visits v
            where v.session_id = p_session_id
              and v.has_order is true
         ),
         test_count = (
           select count(*)::integer
             from mcp.mcp_visits v
            where v.session_id = p_session_id
              and v.has_test is true
         ),
         report_count = (
           select count(*)::integer
             from mcp.mcp_visits v
            where v.session_id = p_session_id
              and v.has_report is true
         ),
         followup_count = (
           select count(*)::integer
             from mcp.mcp_followups f
            where f.session_id = p_session_id
              and coalesce(f.status, 'open') = 'open'
         ),
         updated_at = now()
   where s.id = p_session_id;
end;
$$;

-- Source: 20260704_mcp_standardize_session_counters.sql
create or replace function mcp.mcp_recalc_after_session_customer_change()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  perform mcp.mcp_recalc_route_session_counters(coalesce(new.session_id, old.session_id));
  if tg_op = 'UPDATE' and old.session_id is distinct from new.session_id then
    perform mcp.mcp_recalc_route_session_counters(old.session_id);
  end if;
  return coalesce(new, old);
end;
$$;

