create or replace function mcp.mcp_recalc_after_followup_change()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  perform mcp.mcp_recalc_session_customer_followup_count(coalesce(new.session_customer_id, old.session_customer_id));
  if tg_op = 'UPDATE' and old.session_customer_id is distinct from new.session_customer_id then
    perform mcp.mcp_recalc_session_customer_followup_count(old.session_customer_id);
