  perform mcp.mcp_recalc_route_session_counters(coalesce(new.session_id, old.session_id));
  if tg_op = 'UPDATE' and old.session_id is distinct from new.session_id then
    perform mcp.mcp_recalc_route_session_counters(old.session_id);
  end if;
  return coalesce(new, old);
end;
$$;

