CREATE OR REPLACE FUNCTION mcp.mcp_update_route_customer(
  p_route_customer_id text,
  p_customer_name text,
  p_phone text,
  p_area text,
  p_address text,
  p_sort_order integer,
  p_note text,
  p_active boolean,
  p_geo_lat double precision,
  p_geo_lng double precision,
  p_geo_accuracy double precision,
  p_geo_source text,
  p_google_maps_url text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $function$
DECLARE
  v_row mcp.mcp_route_customers%rowtype;
BEGIN
  IF NULLIF(btrim(COALESCE(p_route_customer_id, '')), '') IS NULL THEN
    RAISE EXCEPTION 'route_customer_id_required' USING ERRCODE = '23514';
  END IF;
  IF p_customer_name IS NOT NULL AND NULLIF(btrim(p_customer_name), '') IS NULL THEN
    RAISE EXCEPTION 'customer_name_required' USING ERRCODE = '23514';
  END IF;
  IF p_sort_order IS NOT NULL AND p_sort_order < 0 THEN
    RAISE EXCEPTION 'invalid_sort_order' USING ERRCODE = '23514';
  END IF;
  IF (p_geo_lat IS NULL) <> (p_geo_lng IS NULL) THEN
    RAISE EXCEPTION 'geo_coordinates_incomplete' USING ERRCODE = '23514';
  END IF;
  IF p_geo_lat IS NOT NULL AND (p_geo_lat < -90 OR p_geo_lat > 90) THEN
    RAISE EXCEPTION 'invalid_geo_lat' USING ERRCODE = '23514';
  END IF;
  IF p_geo_lng IS NOT NULL AND (p_geo_lng < -180 OR p_geo_lng > 180) THEN
    RAISE EXCEPTION 'invalid_geo_lng' USING ERRCODE = '23514';
  END IF;
  IF p_geo_accuracy IS NOT NULL AND p_geo_accuracy < 0 THEN
    RAISE EXCEPTION 'invalid_geo_accuracy' USING ERRCODE = '23514';
  END IF;

  UPDATE mcp.mcp_route_customers
  SET customer_name = COALESCE(NULLIF(btrim(p_customer_name), ''), customer_name),
      phone = CASE WHEN p_phone IS NULL THEN phone ELSE NULLIF(btrim(p_phone), '') END,
      area = CASE WHEN p_area IS NULL THEN area ELSE NULLIF(btrim(p_area), '') END,
      address = CASE WHEN p_address IS NULL THEN address ELSE NULLIF(btrim(p_address), '') END,
      sort_order = COALESCE(p_sort_order, sort_order),
      note = CASE WHEN p_note IS NULL THEN note ELSE NULLIF(btrim(p_note), '') END,
      active = COALESCE(p_active, active),
      geo_lat = CASE WHEN p_geo_lat IS NULL THEN geo_lat ELSE p_geo_lat END,
      geo_lng = CASE WHEN p_geo_lng IS NULL THEN geo_lng ELSE p_geo_lng END,
      geo_accuracy = CASE WHEN p_geo_lat IS NULL THEN geo_accuracy ELSE p_geo_accuracy END,
      geo_captured_at = CASE WHEN p_geo_lat IS NULL THEN geo_captured_at ELSE now() END,
      geo_source = CASE WHEN p_geo_lat IS NULL THEN geo_source ELSE COALESCE(NULLIF(btrim(p_geo_source), ''), 'browser') END,
      google_maps_url = CASE WHEN p_google_maps_url IS NULL THEN google_maps_url ELSE NULLIF(btrim(p_google_maps_url), '') END,
      sync_status = 'synced',
      raw_payload = COALESCE(raw_payload, '{}'::jsonb) || jsonb_build_object('last_source', 'mcp_update_route_customer'),
      updated_at = now()
  WHERE id = p_route_customer_id
  RETURNING * INTO v_row;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'route_customer_not_found' USING ERRCODE = '23503';
  END IF;

  RETURN to_jsonb(v_row);
END;
$function$;

-- Source: 20260717183000_single_active_route_session.sql
create or replace function mcp.mcp_open_route_session(
  p_route_id text,
  p_session_date date,
  p_owner text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $function$
declare
  v_route mcp.mcp_routes%rowtype;
  v_session mcp.mcp_route_sessions%rowtype;
  v_previous mcp.mcp_route_sessions%rowtype;
  v_same_date_exists boolean := false;
  v_previous_has_activity boolean := false;
  v_created boolean := false;
  v_backfill jsonb;
  v_snapshot_count integer := 0;
  v_active_route_customers integer := 0;
  v_now timestamptz := now();
begin
  if nullif(btrim(coalesce(p_route_id, '')), '') is null then
    raise exception 'route_id_required' using errcode = '23514';
  end if;
  if p_session_date is null then
    raise exception 'session_date_required' using errcode = '23514';
  end if;

  -- Match the Foundation mutation lock order: session first, then route. This
  -- avoids route->session / session->route deadlocks with add-customer flows.
  select *
    into v_session
    from mcp.mcp_route_sessions
   where route_id = p_route_id
     and session_date = p_session_date
   for update;
  v_same_date_exists := found;

  if not v_same_date_exists then
    select *
      into v_previous
      from mcp.mcp_route_sessions
     where route_id = p_route_id
       and lower(coalesce(status, 'active')) = 'active'
     order by session_date desc, created_at desc, id desc
     for update
     limit 1;
  end if;

  select *
    into v_route
    from mcp.mcp_routes
   where id = p_route_id
   for update;

  if not found then
    raise exception 'route_not_found' using errcode = '23503';
  end if;
  if coalesce(v_route.active, true) is false then
    raise exception 'route_inactive' using errcode = '23514';
  end if;

  if v_same_date_exists then
    select count(*)::integer
      into v_snapshot_count
      from mcp.mcp_session_customers
     where session_id = v_session.id;

    select count(*)::integer
      into v_active_route_customers
      from mcp.mcp_route_customers
     where route_id = v_session.route_id
       and coalesce(active, true) is true;

    v_backfill := jsonb_build_object(
      'sessionId', v_session.id,
      'routeId', v_session.route_id,
      'beforeCount', v_snapshot_count,
      'insertedCount', 0,
      'activeRouteCustomers', v_active_route_customers,
      'skipped', 'existing_session_snapshot_frozen'
    );
  else
    -- Opening a newer daily run is an explicit lifecycle boundary. Finalize an
    -- older active run first, preserving all child rows and creating the normal
    -- close-session report snapshot when that run contains activity.
    if v_previous.id is not null and v_previous.session_date < p_session_date then
      perform mcp.mcp_recalc_route_session_counters(v_previous.id);

      select *
        into v_previous
        from mcp.mcp_route_sessions
       where id = v_previous.id
       for update;

      v_previous_has_activity :=
        coalesce(v_previous.visited_customers, 0) > 0
        or coalesce(v_previous.order_count, 0) > 0
        or coalesce(v_previous.test_count, 0) > 0
        or coalesce(v_previous.report_count, 0) > 0
        or coalesce(v_previous.followup_count, 0) > 0
        or exists (
          select 1
            from mcp.mcp_visits
           where session_id = v_previous.id
        )
        or exists (
          select 1
            from mcp.mcp_session_customers
           where session_id = v_previous.id
             and (
               checkin_at is not null
               or visit_status in ('visited', 'skipped', 'cancelled')
               or visit_id is not null
               or order_id is not null
               or test_id is not null
               or report_id is not null
               or coalesce(followup_count, 0) > 0
             )
        );

      if v_previous_has_activity then
        perform mcp.mcp_update_route_session(
          v_previous.id,
          v_previous.session_date,
          'done',
          null
        );
      else
        perform mcp.mcp_update_route_session(
          v_previous.id,
          v_previous.session_date,
          'cancelled',
          null
        );
      end if;
    end if;

    insert into mcp.mcp_route_sessions (
      id,
      route_id,
      route_name,
      session_date,
      weekday,
      sales,
      area,
      status,
      planned_customers,
      visited_customers,
      order_count,
      test_count,
      report_count,
      followup_count,
      note,
      sync_status,
      raw_payload,
      created_at,
      updated_at
    ) values (
      'mrs_' || replace(gen_random_uuid()::text, '-', ''),
      v_route.id,
      coalesce(nullif(btrim(v_route.route_name), ''), v_route.id),
      p_session_date,
      extract(dow from p_session_date)::integer,
      coalesce(nullif(btrim(coalesce(p_owner, '')), ''), 'Sale'),
      v_route.area,
      'active',
      0,
      0,
      0,
      0,
      0,
      0,
      'Opened by MCP VPS backend',
      'synced',
      jsonb_build_object(
        'source', 'mcp_open_route_session',
        'route_snapshot', to_jsonb(v_route)
      ),
      v_now,
      v_now
    )
    on conflict (route_id, session_date) do nothing
    returning * into v_session;

    v_created := found;

    if v_created then
      v_backfill := mcp.mcp_backfill_session_customers_from_route(v_session.id, true);
      perform mcp.mcp_recalc_route_session_counters(v_session.id);
    else
      select *
        into v_session
        from mcp.mcp_route_sessions
       where route_id = p_route_id
         and session_date = p_session_date
       for update;

      if v_session.id is null then
        raise exception 'route_session_create_failed' using errcode = 'P0001';
      end if;

      select count(*)::integer
        into v_snapshot_count
        from mcp.mcp_session_customers
       where session_id = v_session.id;

      select count(*)::integer
        into v_active_route_customers
        from mcp.mcp_route_customers
       where route_id = v_session.route_id
         and coalesce(active, true) is true;

      v_backfill := jsonb_build_object(
        'sessionId', v_session.id,
        'routeId', v_session.route_id,
        'beforeCount', v_snapshot_count,
        'insertedCount', 0,
        'activeRouteCustomers', v_active_route_customers,
        'skipped', 'existing_session_snapshot_frozen'
      );
    end if;
  end if;

  select *
    into v_session
    from mcp.mcp_route_sessions
   where id = v_session.id;

  return jsonb_build_object(
    'created', v_created,
    'session', jsonb_build_object(
      'id', v_session.id,
      'sessionId', v_session.id,
      'routeId', v_session.route_id,
      'routeName', v_session.route_name,
      'sessionDate', v_session.session_date,
      'date', v_session.session_date,
      'weekday', v_session.weekday,
      'owner', coalesce(v_session.sales, 'Sale'),
      'area', v_session.area,
      'status', case when v_session.status = 'completed' then 'done' else v_session.status end,
      'plannedCustomers', coalesce(v_session.planned_customers, 0),
      'visitedCustomers', coalesce(v_session.visited_customers, 0),
      'orderCount', coalesce(v_session.order_count, 0),
      'testCount', coalesce(v_session.test_count, 0),
      'reportCount', coalesce(v_session.report_count, 0),
      'followupCount', coalesce(v_session.followup_count, 0),
      'note', v_session.note,
      'createdAt', v_session.created_at,
      'updatedAt', v_session.updated_at
    ),
    'backfill', v_backfill
  );
end;
$function$;

-- Source: 20260712025937_freeze_mcp_v1_contract_20260711.sql
create or replace function mcp.mcp_set_session_customer_status(
  p_session_customer_id text,
  p_visit_status text,
  p_status_reason text default null,
  p_note text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $function$
declare
  v_sc mcp.mcp_session_customers%rowtype;
  v_sess mcp.mcp_route_sessions%rowtype;
  v_visit mcp.mcp_visits%rowtype;
  v_status text;
  v_reason text;
  v_now timestamptz := now();
  v_has_activity boolean := false;
begin
  if nullif(btrim(coalesce(p_session_customer_id, '')), '') is null then
    raise exception 'session_customer_id_required' using errcode = '23514';
  end if;

  v_status := lower(coalesce(nullif(btrim(coalesce(p_visit_status, '')), ''), 'visited'));
  if v_status not in ('pending', 'visited', 'skipped', 'cancelled') then
    raise exception 'invalid_visit_status' using errcode = '23514';
  end if;

  v_reason := nullif(btrim(coalesce(p_status_reason, '')), '');
  if v_status in ('skipped', 'cancelled') and v_reason is null then
    raise exception 'status_reason_required' using errcode = '23514';
  end if;

  select * into v_sc
    from mcp.mcp_session_customers
   where id = p_session_customer_id
   for update;
  if not found then
    raise exception 'session_customer_not_found' using errcode = '23503';
  end if;

  select * into v_sess
    from mcp.mcp_route_sessions
   where id = v_sc.session_id
   for share;
  if not found then
    raise exception 'session_not_found' using errcode = '23503';
  end if;

  perform mcp.mcp_assert_session_mutable(v_sess.id);

  v_has_activity := v_sc.order_id is not null
                 or v_sc.test_id is not null
                 or v_sc.report_id is not null
                 or coalesce(v_sc.followup_count, 0) > 0;

  if v_status <> 'visited' and v_has_activity then
    raise exception 'session_customer_has_activity' using errcode = '23514';
  end if;

  if v_sc.visit_id is not null then
    select * into v_visit from mcp.mcp_visits where id = v_sc.visit_id for update;
    if v_visit.id is not null and v_status <> 'visited'
       and (coalesce(v_visit.has_order, false) or coalesce(v_visit.has_test, false) or coalesce(v_visit.has_report, false)) then
      raise exception 'session_customer_has_activity' using errcode = '23514';
    end if;
  end if;

  if v_status = 'visited' then
    if v_visit.id is null then
      insert into mcp.mcp_visits (
        id, session_id, route_id, route_customer_id, visit_date, status,
        has_order, has_test, has_report, checkin_at, note, raw_payload,
        created_at, updated_at
      ) values (
        'mcv_' || replace(gen_random_uuid()::text, '-', ''),
        v_sc.session_id,
        v_sc.route_id,
        v_sc.route_customer_id,
        v_sess.session_date,
        'visited',
        false, false, false,
        v_now,
        coalesce(nullif(btrim(coalesce(p_note, '')), ''), 'Đã ghé'),
        jsonb_build_object('source', 'mcp_set_session_customer_status', 'session_customer_id', v_sc.id),
        v_now,
        v_now
      ) returning * into v_visit;
    else
      update mcp.mcp_visits
         set visit_date = v_sess.session_date,
             status = 'visited',
             checkin_at = coalesce(checkin_at, v_now),
             note = coalesce(nullif(btrim(coalesce(p_note, '')), ''), note, 'Đã ghé'),
             updated_at = v_now
       where id = v_visit.id
       returning * into v_visit;
    end if;
  elsif v_visit.id is not null then
    update mcp.mcp_visits
       set visit_date = v_sess.session_date,
           status = v_status,
           note = coalesce(nullif(btrim(coalesce(p_note, '')), ''), v_reason, note),
           updated_at = v_now
     where id = v_visit.id
     returning * into v_visit;
  end if;

  update mcp.mcp_session_customers
     set visit_status = v_status,
         status_reason = case when v_status in ('skipped', 'cancelled') then v_reason else null end,
         visit_id = case when v_status = 'visited' then v_visit.id else visit_id end,
         note = coalesce(nullif(btrim(coalesce(p_note, '')), ''), note),
         updated_at = v_now
   where id = v_sc.id
   returning * into v_sc;

  perform mcp.mcp_recalc_route_session_counters(v_sc.session_id);

  return jsonb_build_object(
    'sessionCustomer', to_jsonb(v_sc),
    'visit', case when v_visit.id is null then null else to_jsonb(v_visit) end,
    'sessionId', v_sc.session_id,
    'sessionCustomerId', v_sc.id,
    'visitId', v_visit.id,
    'visitStatus', v_status
  );
end;
$function$;

-- Source: 20260712025937_freeze_mcp_v1_contract_20260711.sql
create or replace function mcp.mcp_update_route_session(
  p_session_id text,
  p_session_date date default null,
  p_status text default null,
  p_note text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $function$
declare
  v_sess mcp.mcp_route_sessions%rowtype;
  v_old_date date;
  v_status text;
  v_date date;
  v_now timestamptz := now();
  v_snapshot jsonb := null;
begin
  if nullif(btrim(coalesce(p_session_id, '')), '') is null then
    raise exception 'session_id_required' using errcode = '23514';
  end if;

  select * into v_sess
    from mcp.mcp_route_sessions
   where id = p_session_id
   for update;
  if not found then
    raise exception 'session_not_found' using errcode = '23503';
  end if;

  if lower(coalesce(v_sess.status, 'active')) in ('done', 'completed', 'cancelled') then
    raise exception 'session_closed_read_only' using errcode = '23514';
  end if;

  v_old_date := v_sess.session_date;
  v_status := lower(coalesce(nullif(btrim(coalesce(p_status, '')), ''), v_sess.status, 'active'));
  if v_status = 'completed' then v_status := 'done'; end if;
  if v_status not in ('active', 'done', 'cancelled') then
    raise exception 'invalid_session_status' using errcode = '23514';
  end if;
  v_date := coalesce(p_session_date, v_old_date);

  if v_date <> v_old_date then
    update mcp.mcp_visits
       set visit_date = v_date,
           updated_at = v_now
     where session_id = v_sess.id;
  end if;

  update mcp.mcp_route_sessions
     set session_date = v_date,
         weekday = extract(dow from v_date)::integer,
         status = v_status,
         note = case when p_note is null then note else nullif(btrim(p_note), '') end,
         updated_at = v_now
   where id = v_sess.id
   returning * into v_sess;

  perform mcp.mcp_recalc_route_session_counters(v_sess.id);

  if v_status = 'done' then
    v_snapshot := mcp.mcp_create_session_report_snapshot(v_sess.id, 'close_session');
  end if;

  return jsonb_build_object(
    'id', v_sess.id,
    'routeId', v_sess.route_id,
    'routeName', v_sess.route_name,
    'sessionDate', v_sess.session_date,
    'status', v_status,
    'note', coalesce(v_sess.note, ''),
    'snapshot', v_snapshot
  );
end;
$function$;

-- Source: 20260712033916_fix_mcp_open_session_snapshot_once_20260712.sql
create or replace function mcp.mcp_delete_empty_route_session(p_session_id text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $function$
declare
  sess mcp.mcp_route_sessions%rowtype;
  v_snapshot_count integer := 0;
  v_snapshot_activity_count integer := 0;
  v_visit_count integer := 0;
  v_followup_count integer := 0;
  v_report_count integer := 0;
  v_snapshot_deleted integer := 0;
  v_visit_deleted integer := 0;
  v_session_deleted integer := 0;
begin
  if nullif(trim(p_session_id), '') is null then
    raise exception 'session_id_required' using errcode = '23514';
  end if;

  select *
    into sess
    from mcp.mcp_route_sessions
   where id = p_session_id
   for update;

  if not found then
    raise exception 'session_not_found' using errcode = '23503';
  end if;

  if lower(coalesce(sess.status, '')) in ('done', 'completed') then
    raise exception 'session_closed_cannot_delete' using errcode = '23514';
  end if;

  select
    count(*),
    count(*) filter (
      where coalesce(visit_status, 'pending') <> 'pending'
         or visit_id is not null
         or order_id is not null
         or test_id is not null
         or report_id is not null
         or coalesce(followup_count, 0) > 0
    )
    into v_snapshot_count, v_snapshot_activity_count
    from mcp.mcp_session_customers
   where session_id = sess.id;

  select count(*)
    into v_visit_count
    from mcp.mcp_visits
   where session_id = sess.id;

  select count(*)
    into v_followup_count
    from mcp.mcp_followups
   where session_id = sess.id;

  select count(*)
    into v_report_count
    from mcp.mcp_session_reports
   where session_id = sess.id;

  if v_snapshot_activity_count > 0
     or v_visit_count > 0
     or v_followup_count > 0
     or v_report_count > 0
     or coalesce(sess.visited_customers, 0) > 0
     or coalesce(sess.order_count, 0) > 0
     or coalesce(sess.test_count, 0) > 0
     or coalesce(sess.report_count, 0) > 0
     or coalesce(sess.followup_count, 0) > 0
  then
    raise exception 'session_has_activity_cancel_instead'
      using errcode = '23514',
            detail = jsonb_build_object(
              'snapshotActivityCount', v_snapshot_activity_count,
              'visitCount', v_visit_count,
              'followupCount', v_followup_count,
              'reportCount', v_report_count,
              'orderCount', coalesce(sess.order_count, 0),
              'testCount', coalesce(sess.test_count, 0)
            )::text;
  end if;

  perform set_config('mcp.internal_hard_delete', 'on', true);

  delete from mcp.mcp_visits
   where session_id = sess.id;
  get diagnostics v_visit_deleted = row_count;

  delete from mcp.mcp_session_customers
   where session_id = sess.id;
  get diagnostics v_snapshot_deleted = row_count;

  delete from mcp.mcp_route_sessions
   where id = sess.id;
  get diagnostics v_session_deleted = row_count;

  if v_session_deleted <> 1 then
    raise exception 'session_delete_not_applied' using errcode = 'P0001';
  end if;

  return jsonb_build_object(
    'id', sess.id,
    'deleted', true,
    'snapshotCount', v_snapshot_count,
    'snapshotDeleted', v_snapshot_deleted,
    'visitDeleted', v_visit_deleted
  );
end;
$function$;

-- Source: 20260715101500_add_atomic_session_customer_mutations.sql
create or replace function mcp.mcp_record_session_customer_result(
  p_session_customer_id text,
  p_result_type text default null,
  p_note text default null,
  p_order_id text default null,
  p_test_id text default null,
  p_report_id text default null,
  p_has_order boolean default null,
  p_has_test boolean default null,
  p_has_report boolean default null,
  p_context jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $function$
declare
  v_sc mcp.mcp_session_customers%rowtype;
  v_visit mcp.mcp_visits%rowtype;
  v_session mcp.mcp_route_sessions%rowtype;
  v_result_type text := lower(nullif(btrim(coalesce(p_result_type, '')), ''));
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_order_id text;
  v_test_id text;
  v_report_id text;
  v_has_order boolean;
  v_has_test boolean;
  v_has_report boolean;
  v_created_visit boolean := false;
  v_snapshot_count integer := 0;
  v_now timestamptz := now();
begin
  if nullif(btrim(coalesce(p_session_customer_id, '')), '') is null then
    raise exception 'session_customer_id_required' using errcode = '23514';
  end if;

  if v_result_type is not null and v_result_type not in ('order', 'test', 'report') then
    raise exception 'invalid_result_type' using errcode = '23514';
  end if;

  if v_result_type is null
     and v_note is null
     and nullif(btrim(coalesce(p_order_id, '')), '') is null
     and nullif(btrim(coalesce(p_test_id, '')), '') is null
     and nullif(btrim(coalesce(p_report_id, '')), '') is null
     and p_has_order is null
     and p_has_test is null
     and p_has_report is null then
    raise exception 'result_required' using errcode = '23514';
  end if;

  select * into v_sc
    from mcp.mcp_session_customers
   where id = p_session_customer_id
   for update;

  if not found then
    raise exception 'session_customer_not_found' using errcode = '23503';
  end if;

  select * into v_session
    from mcp.mcp_route_sessions
   where id = v_sc.session_id
   for share;

  if not found then
    raise exception 'session_not_found' using errcode = '23503';
  end if;

  perform mcp.mcp_assert_session_mutable(v_session.id);

  if v_sc.visit_id is not null then
    select * into v_visit
      from mcp.mcp_visits
     where id = v_sc.visit_id
     for update;
  end if;

  if v_visit.id is null then
    insert into mcp.mcp_visits (
      id,
      session_id,
      route_id,
      route_customer_id,
      visit_date,
      status,
      has_order,
      has_test,
      has_report,
      checkin_at,
      note,
      raw_payload,
      created_at,
      updated_at
    ) values (
      'mcv_' || replace(gen_random_uuid()::text, '-', ''),
      v_sc.session_id,
      v_sc.route_id,
      v_sc.route_customer_id,
      v_session.session_date,
      'visited',
      false,
      false,
      false,
      v_now,
      coalesce(v_note, v_sc.note, 'Đã ghi kết quả'),
      jsonb_build_object(
        'source', 'mcp_record_session_customer_result',
        'session_customer_id', v_sc.id,
        'foundation_context', coalesce(p_context, '{}'::jsonb)
      ),
      v_now,
      v_now
    )
    returning * into v_visit;

    v_created_visit := true;
  end if;

  v_order_id := coalesce(
    nullif(btrim(coalesce(p_order_id, '')), ''),
    v_sc.order_id,
    v_visit.order_id
  );
  v_test_id := coalesce(
    nullif(btrim(coalesce(p_test_id, '')), ''),
    v_sc.test_id,
    v_visit.test_id
  );
  v_report_id := coalesce(
    nullif(btrim(coalesce(p_report_id, '')), ''),
    v_sc.report_id,
    v_visit.report_id
  );

  -- Result flags are monotonic. An explicit false cannot erase activity that
  -- already exists or contradict a linked business record.
  v_has_order := coalesce(v_visit.has_order, false)
                 or v_order_id is not null
                 or v_result_type = 'order'
                 or coalesce(p_has_order, false);
  v_has_test := coalesce(v_visit.has_test, false)
                or v_test_id is not null
                or v_result_type = 'test'
                or coalesce(p_has_test, false);
  v_has_report := coalesce(v_visit.has_report, false)
                  or v_report_id is not null
                  or v_result_type = 'report'
                  or coalesce(p_has_report, false);

  update mcp.mcp_visits
     set visit_date = v_session.session_date,
         status = 'visited',
         has_order = v_has_order,
         has_test = v_has_test,
         has_report = v_has_report,
         order_id = v_order_id,
         test_id = v_test_id,
         report_id = v_report_id,
         checkin_at = coalesce(checkin_at, v_now),
         note = coalesce(v_note, note, v_sc.note, 'Đã ghi kết quả'),
         raw_payload = coalesce(raw_payload, '{}'::jsonb) || jsonb_build_object(
           'last_result_source', 'mcp_record_session_customer_result',
           'last_result_context', coalesce(p_context, '{}'::jsonb)
         ),
         updated_at = v_now
   where id = v_visit.id
   returning * into v_visit;

  update mcp.mcp_session_customers
     set visit_status = 'visited',
         status_reason = null,
         visit_id = v_visit.id,
         order_id = v_order_id,
         test_id = v_test_id,
         report_id = v_report_id,
         note = coalesce(v_note, note),
         raw_payload = coalesce(raw_payload, '{}'::jsonb) || jsonb_build_object(
           'last_result_source', 'mcp_record_session_customer_result',
           'last_result_context', coalesce(p_context, '{}'::jsonb)
         ),
         updated_at = v_now
   where id = v_sc.id
   returning * into v_sc;

  perform mcp.mcp_recalc_route_session_counters(v_sc.session_id);

  select * into v_session
    from mcp.mcp_route_sessions
   where id = v_sc.session_id;

  select count(*)::integer into v_snapshot_count
    from mcp.mcp_session_customers
   where session_id = v_sc.session_id;

  return jsonb_build_object(
    'sessionCustomer', to_jsonb(v_sc),
    'visit', to_jsonb(v_visit),
    'createdVisit', v_created_visit,
    'counters', jsonb_build_object(
      'session', to_jsonb(v_session),
      'snapshotCount', v_snapshot_count,
      'visitedCount', coalesce(v_session.visited_customers, 0),
      'orderCount', coalesce(v_session.order_count, 0),
      'testCount', coalesce(v_session.test_count, 0),
      'reportCount', coalesce(v_session.report_count, 0),
      'followupCount', coalesce(v_session.followup_count, 0)
    )
  );
end;
$function$;

-- Source: 20260716144500_add_session_customer_gps.sql
create or replace function mcp.mcp_add_session_customer(
  p_session_id text,
  p_customer_name text,
  p_route_customer_id text default null,
  p_customer_id text default null,
  p_phone text default null,
  p_area text default null,
  p_address text default null,
  p_note text default null,
  p_context jsonb default '{}'::jsonb,
  p_geo_lat double precision default null,
  p_geo_lng double precision default null,
  p_geo_accuracy double precision default null,
  p_geo_source text default null,
  p_google_maps_url text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $function$
declare
  v_session mcp.mcp_route_sessions%rowtype;
  v_route mcp.mcp_routes%rowtype;
  v_route_customer mcp.mcp_route_customers%rowtype;
  v_sc mcp.mcp_session_customers%rowtype;
  v_existing mcp.mcp_session_customers%rowtype;
  v_route_customer_id text := nullif(btrim(coalesce(p_route_customer_id, '')), '');
  v_customer_id text := nullif(btrim(coalesce(p_customer_id, '')), '');
  v_customer_name text := nullif(btrim(coalesce(p_customer_name, '')), '');
  v_phone text := nullif(btrim(coalesce(p_phone, '')), '');
  v_phone_digits text := nullif(regexp_replace(coalesce(p_phone, ''), '[^0-9]+', '', 'g'), '');
  v_area text := nullif(btrim(coalesce(p_area, '')), '');
  v_address text := nullif(btrim(coalesce(p_address, '')), '');
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_geo_source text := nullif(btrim(coalesce(p_geo_source, '')), '');
  v_google_maps_url text := nullif(btrim(coalesce(p_google_maps_url, '')), '');
  v_route_sort_order integer := 1;
  v_session_sort_order integer := 1;
  v_snapshot_count integer := 0;
  v_route_customer_created boolean := false;
  v_route_customer_reactivated boolean := false;
  v_now timestamptz := now();
begin
  if nullif(btrim(coalesce(p_session_id, '')), '') is null then
    raise exception 'session_id_required' using errcode = '23514';
  end if;

  if v_customer_name is null then
    raise exception 'customer_name_required' using errcode = '23514';
  end if;

  if (p_geo_lat is null) <> (p_geo_lng is null) then
    raise exception 'geo_coordinates_incomplete' using errcode = '23514';
  end if;

  if p_geo_lat is not null and (p_geo_lat < -90 or p_geo_lat > 90) then
    raise exception 'invalid_geo_lat' using errcode = '23514';
  end if;

  if p_geo_lng is not null and (p_geo_lng < -180 or p_geo_lng > 180) then
    raise exception 'invalid_geo_lng' using errcode = '23514';
  end if;

  if p_geo_accuracy is not null and p_geo_accuracy < 0 then
    raise exception 'invalid_geo_accuracy' using errcode = '23514';
  end if;

  if p_geo_lat is not null and p_geo_lng is not null then
    v_geo_source := coalesce(v_geo_source, 'browser');
    v_google_maps_url := coalesce(
      v_google_maps_url,
      'https://www.google.com/maps/search/?api=1&query=' || p_geo_lat::text || ',' || p_geo_lng::text
    );
  end if;

  -- The session row serializes snapshot insertion and protects sort order.
  select * into v_session
    from mcp.mcp_route_sessions
   where id = p_session_id
   for update;

  if not found then
    raise exception 'session_not_found' using errcode = '23503';
  end if;

  perform mcp.mcp_assert_session_mutable(v_session.id);

  -- The route row serializes route-customer matching/creation for this flow.
  select * into v_route
    from mcp.mcp_routes
   where id = v_session.route_id
   for update;

  if not found then
    raise exception 'route_not_found' using errcode = '23503';
  end if;

  if v_route_customer_id is not null then
    select * into v_route_customer
      from mcp.mcp_route_customers
     where id = v_route_customer_id
     for update;

    if not found then
      raise exception 'route_customer_not_found' using errcode = '23503';
    end if;

    if v_route_customer.route_id is distinct from v_session.route_id then
      raise exception 'route_customer_route_mismatch' using errcode = '23514';
    end if;
  else
    -- Prefer a phone match. Formatting differences do not create duplicates.
    if v_phone_digits is not null then
      select * into v_route_customer
        from mcp.mcp_route_customers
       where route_id = v_session.route_id
         and nullif(regexp_replace(coalesce(phone, ''), '[^0-9]+', '', 'g'), '') = v_phone_digits
       order by coalesce(active, true) desc, updated_at desc nulls last
       for update
       limit 1;
    end if;

    -- Without a phone, use exact normalized name plus address, or name plus area.
    if v_route_customer.id is null then
      select * into v_route_customer
        from mcp.mcp_route_customers
       where route_id = v_session.route_id
         and lower(btrim(customer_name)) = lower(v_customer_name)
         and (
           (v_address is not null and lower(btrim(coalesce(address, ''))) = lower(v_address))
           or
           (v_address is null and lower(btrim(coalesce(area, ''))) = lower(btrim(coalesce(v_area, v_session.area, ''))))
         )
       order by coalesce(active, true) desc, updated_at desc nulls last
       for update
       limit 1;
    end if;
  end if;

  if v_route_customer.id is not null then
    v_route_customer_reactivated := coalesce(v_route_customer.active, false) is false;

    update mcp.mcp_route_customers
       set customer_id = coalesce(v_customer_id, customer_id),
           customer_name = v_customer_name,
           phone = coalesce(v_phone, phone),
           area = coalesce(v_area, area, v_session.area),
           address = coalesce(v_address, address),
           active = true,
           note = coalesce(v_note, note),
           geo_lat = case when p_geo_lat is not null then p_geo_lat else geo_lat end,
           geo_lng = case when p_geo_lng is not null then p_geo_lng else geo_lng end,
           geo_accuracy = case when p_geo_lat is not null then p_geo_accuracy else geo_accuracy end,
           geo_captured_at = case when p_geo_lat is not null then v_now else geo_captured_at end,
           geo_source = case when p_geo_lat is not null then v_geo_source else geo_source end,
           google_maps_url = coalesce(v_google_maps_url, google_maps_url),
           raw_payload = coalesce(raw_payload, '{}'::jsonb) || jsonb_build_object(
             'last_source', 'mcp_add_session_customer',
             'last_session_id', v_session.id,
             'location_captured', p_geo_lat is not null,
             'foundation_context', coalesce(p_context, '{}'::jsonb)
           ),
           updated_at = v_now
     where id = v_route_customer.id
     returning * into v_route_customer;
  else
    select coalesce(max(sort_order), 0) + 1
      into v_route_sort_order
      from mcp.mcp_route_customers
     where route_id = v_session.route_id;

    insert into mcp.mcp_route_customers (
      id,
      route_id,
      customer_id,
      customer_name,
      phone,
      area,
      address,
      sort_order,
      active,
      note,
      geo_lat,
      geo_lng,
      geo_accuracy,
      geo_captured_at,
      geo_source,
      google_maps_url,
      raw_payload,
      created_at,
      updated_at
    ) values (
      'mrc_' || replace(gen_random_uuid()::text, '-', ''),
      v_session.route_id,
      v_customer_id,
      v_customer_name,
      v_phone,
      coalesce(v_area, v_session.area),
      v_address,
      v_route_sort_order,
      true,
      coalesce(v_note, 'Thêm trực tiếp từ phiên đi tuyến'),
      p_geo_lat,
      p_geo_lng,
      p_geo_accuracy,
      case when p_geo_lat is not null then v_now else null end,
      case when p_geo_lat is not null then v_geo_source else null end,
      v_google_maps_url,
      jsonb_build_object(
        'source', 'mcp_add_session_customer',
        'created_from_session_id', v_session.id,
        'location_captured', p_geo_lat is not null,
        'foundation_context', coalesce(p_context, '{}'::jsonb)
      ),
      v_now,
      v_now
    )
    returning * into v_route_customer;

    v_route_customer_created := true;
  end if;

  v_route_customer_id := v_route_customer.id;

  -- A retry reuses the route customer and the existing session snapshot.
  select * into v_existing
    from mcp.mcp_session_customers
   where session_id = v_session.id
     and route_customer_id = v_route_customer_id;

  if v_existing.id is not null then
    perform mcp.mcp_recalc_route_session_counters(v_session.id);
    select * into v_session from mcp.mcp_route_sessions where id = v_session.id;
    select count(*)::integer into v_snapshot_count
      from mcp.mcp_session_customers
     where session_id = v_session.id;

    return jsonb_build_object(
      'routeCustomer', to_jsonb(v_route_customer),
      'sessionCustomer', to_jsonb(v_existing),
      'created', false,
      'createdSessionCustomer', false,
      'createdRouteCustomer', v_route_customer_created,
      'reactivatedRouteCustomer', v_route_customer_reactivated,
      'counters', jsonb_build_object(
        'session', to_jsonb(v_session),
        'snapshotCount', v_snapshot_count,
        'visitedCount', coalesce(v_session.visited_customers, 0),
        'orderCount', coalesce(v_session.order_count, 0),
        'testCount', coalesce(v_session.test_count, 0),
        'reportCount', coalesce(v_session.report_count, 0),
        'followupCount', coalesce(v_session.followup_count, 0)
      )
    );
  end if;

  select coalesce(max(sort_order), 0) + 1
    into v_session_sort_order
    from mcp.mcp_session_customers
   where session_id = v_session.id;

  insert into mcp.mcp_session_customers (
    id,
    session_id,
    route_id,
    route_customer_id,
    customer_id,
    customer_name,
    phone,
    area,
    address,
    sort_order,
    source,
    planned_status,
    visit_status,
    note,
    raw_payload,
    created_at,
    updated_at
  ) values (
    'msc_' || replace(gen_random_uuid()::text, '-', ''),
    v_session.id,
    v_session.route_id,
    v_route_customer.id,
    v_route_customer.customer_id,
    v_route_customer.customer_name,
    v_route_customer.phone,
    coalesce(v_route_customer.area, v_session.area),
    v_route_customer.address,
    v_session_sort_order,
    'added',
    'added',
    'pending',
    coalesce(v_note, 'Khách thêm trực tiếp trong phiên'),
    jsonb_build_object(
      'source', 'mcp_add_session_customer',
      'session_id', v_session.id,
      'route_customer_id', v_route_customer.id,
      'created_route_customer', v_route_customer_created,
      'location_captured', p_geo_lat is not null,
      'foundation_context', coalesce(p_context, '{}'::jsonb)
    ),
    v_now,
    v_now
  )
  returning * into v_sc;

  perform mcp.mcp_recalc_route_session_counters(v_session.id);

  select * into v_session
    from mcp.mcp_route_sessions
   where id = v_session.id;

  select count(*)::integer into v_snapshot_count
    from mcp.mcp_session_customers
   where session_id = v_session.id;

  return jsonb_build_object(
    'routeCustomer', to_jsonb(v_route_customer),
    'sessionCustomer', to_jsonb(v_sc),
    'created', true,
    'createdSessionCustomer', true,
    'createdRouteCustomer', v_route_customer_created,
    'reactivatedRouteCustomer', v_route_customer_reactivated,
    'counters', jsonb_build_object(
      'session', to_jsonb(v_session),
      'snapshotCount', v_snapshot_count,
      'visitedCount', coalesce(v_session.visited_customers, 0),
      'orderCount', coalesce(v_session.order_count, 0),
      'testCount', coalesce(v_session.test_count, 0),
      'reportCount', coalesce(v_session.report_count, 0),
      'followupCount', coalesce(v_session.followup_count, 0)
    )
  );
end;
$function$;

-- Source: 20260717124500_session_customer_checkin.sql
create or replace function mcp.mcp_set_session_customer_checkin(
  p_session_customer_id text,
  p_checked_in boolean,
  p_geo_lat double precision default null,
  p_geo_lng double precision default null,
  p_geo_accuracy double precision default null,
  p_geo_source text default null,
  p_context jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $function$
declare
  v_sc mcp.mcp_session_customers%rowtype;
  v_now timestamptz := now();
  v_source text := nullif(btrim(coalesce(p_geo_source, '')), '');
  v_context jsonb := coalesce(p_context, '{}'::jsonb);
  v_raw_payload jsonb;
begin
  if nullif(btrim(coalesce(p_session_customer_id, '')), '') is null then
    raise exception 'session_customer_id_required' using errcode = '23514';
  end if;
  if p_checked_in is null then
    raise exception 'checked_in_required' using errcode = '23514';
  end if;
  if jsonb_typeof(v_context) <> 'object' then
    raise exception 'invalid_context' using errcode = '23514';
  end if;

  if p_checked_in then
    if p_geo_lat is null or p_geo_lng is null then
      raise exception 'checkin_coordinates_required' using errcode = '23514';
    end if;
    if p_geo_lat < -90 or p_geo_lat > 90 then
      raise exception 'invalid_geo_lat' using errcode = '23514';
    end if;
    if p_geo_lng < -180 or p_geo_lng > 180 then
      raise exception 'invalid_geo_lng' using errcode = '23514';
    end if;
    if p_geo_accuracy is not null and p_geo_accuracy < 0 then
      raise exception 'invalid_geo_accuracy' using errcode = '23514';
    end if;
    v_source := coalesce(v_source, 'browser_manual');
  elsif p_geo_lat is not null or p_geo_lng is not null or p_geo_accuracy is not null then
    raise exception 'checkin_coordinates_not_allowed' using errcode = '23514';
  end if;

  select *
    into v_sc
    from mcp.mcp_session_customers
   where id = p_session_customer_id
   for update;

  if not found then
    raise exception 'session_customer_not_found' using errcode = 'P0002';
  end if;

  perform mcp.mcp_assert_session_mutable(v_sc.session_id);

  v_raw_payload := coalesce(v_sc.raw_payload, '{}'::jsonb) - 'sales_checkin';
  if p_checked_in then
    v_raw_payload := v_raw_payload || jsonb_build_object(
      'sales_checkin', jsonb_build_object(
        'lat', p_geo_lat,
        'lng', p_geo_lng,
        'accuracy', p_geo_accuracy,
        'capturedAt', v_now,
        'source', v_source
      )
    );
  end if;
  v_raw_payload := v_raw_payload || jsonb_build_object(
    'sales_checkin_last_action', case when p_checked_in then 'checked_in' else 'removed' end,
    'sales_checkin_context', v_context
  );

  update mcp.mcp_session_customers
     set checkin_lat = case when p_checked_in then p_geo_lat else null end,
         checkin_lng = case when p_checked_in then p_geo_lng else null end,
         checkin_accuracy = case when p_checked_in then p_geo_accuracy else null end,
         checkin_at = case when p_checked_in then v_now else null end,
         checkin_source = case when p_checked_in then v_source else null end,
         raw_payload = v_raw_payload,
         updated_at = v_now
   where id = v_sc.id
   returning * into v_sc;

  return jsonb_build_object(
    'sessionCustomer', to_jsonb(v_sc),
    'sessionCustomerId', v_sc.id,
    'checkedIn', v_sc.checkin_at is not null,
    'checkinAt', v_sc.checkin_at,
    'geoLat', v_sc.checkin_lat,
    'geoLng', v_sc.checkin_lng,
    'geoAccuracy', v_sc.checkin_accuracy,
    'geoSource', v_sc.checkin_source
  );
end;
$function$;

-- Source: 20260705_order_variant_id_rpc.sql
create or replace function mcp.mcp_create_order_from_session_customer(
  p_session_customer_id text,
  p_items jsonb,
  p_note text default null,
  p_status text default 'confirmed'
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  sc record;
  sess record;
  v_order_id text;
  v_order_code text;
  v_visit_id text;
  now_ts timestamptz := now();
  item jsonb;
  qty numeric;
  unit_price numeric;
  discount numeric;
  line_total numeric;
  subtotal numeric := 0;
  discount_total numeric := 0;
  item_count integer := 0;
begin
  if p_session_customer_id is null or length(trim(p_session_customer_id)) = 0 then
    raise exception 'session_customer_id_required' using errcode = '23514';
  end if;

  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'order_items_required' using errcode = '23514';
  end if;

  select * into sc
    from mcp.mcp_session_customers
   where id = p_session_customer_id;

  if sc.id is null then
    raise exception 'session_customer_not_found' using errcode = '23503';
  end if;

  select * into sess
    from mcp.mcp_route_sessions
   where id = sc.session_id;

  if sess.id is null then
    raise exception 'session_not_found' using errcode = '23503';
  end if;

  v_order_id := 'order_' || replace(gen_random_uuid()::text, '-', '');
  v_order_code := 'MCP-' || to_char(sess.session_date, 'YYYYMMDD') || '-' || substr(v_order_id, 7, 6);

  for item in select value from jsonb_array_elements(p_items) loop
    if length(trim(coalesce(item ->> 'productName', item ->> 'product_name', ''))) = 0 then
      raise exception 'product_name_required' using errcode = '23514';
    end if;

    qty := greatest(coalesce(nullif(item ->> 'quantity', '')::numeric, 0), 0);
    unit_price := greatest(coalesce(nullif(item ->> 'unitPrice', '')::numeric, nullif(item ->> 'unit_price', '')::numeric, 0), 0);
    discount := greatest(coalesce(nullif(item ->> 'discount', '')::numeric, 0), 0);
    subtotal := subtotal + qty * unit_price;
    discount_total := discount_total + discount;
    item_count := item_count + 1;
  end loop;

  insert into mcp.orders (
    id, order_code, order_date, sales, customer_id, customer_name, customer_phone, area,
    delivery_address, source_type, source_id, status, subtotal, discount_total, grand_total,
    note, sync_status, raw_payload, created_at, updated_at
  ) values (
    v_order_id, v_order_code, sess.session_date, sess.sales, sc.customer_id, sc.customer_name, sc.phone, sc.area,
    sc.address, 'mcp_session_customer', sc.id, coalesce(nullif(p_status, ''), 'confirmed'), subtotal, discount_total, greatest(subtotal - discount_total, 0),
    p_note, 'synced', jsonb_build_object('source', 'mcp_create_order_from_session_customer', 'session_id', sc.session_id, 'session_customer_id', sc.id, 'route_id', sc.route_id), now_ts, now_ts
  );

  for item in select value from jsonb_array_elements(p_items) loop
    qty := greatest(coalesce(nullif(item ->> 'quantity', '')::numeric, 0), 0);
    unit_price := greatest(coalesce(nullif(item ->> 'unitPrice', '')::numeric, nullif(item ->> 'unit_price', '')::numeric, 0), 0);
    discount := greatest(coalesce(nullif(item ->> 'discount', '')::numeric, 0), 0);
    line_total := greatest(qty * unit_price - discount, 0);

    insert into mcp.order_items (
      id, order_id, product_id, variant_id, product_name, sku, unit, quantity, unit_price, discount, line_total, note, raw_payload, created_at
    ) values (
      'order_item_' || replace(gen_random_uuid()::text, '-', ''),
      v_order_id,
      nullif(coalesce(item ->> 'productId', item ->> 'product_id'), ''),
      nullif(coalesce(item ->> 'variantId', item ->> 'variant_id'), ''),
      coalesce(item ->> 'productName', item ->> 'product_name'),
      nullif(item ->> 'sku', ''),
      nullif(item ->> 'unit', ''),
      qty,
      unit_price,
      discount,
      line_total,
      nullif(item ->> 'note', ''),
      item,
      now_ts
    );
  end loop;

  if sc.visit_id is not null then
    update mcp.mcp_visits
       set has_order = true,
           order_id = v_order_id,
           status = 'visited',
           note = coalesce(nullif(p_note, ''), note, 'Tạo đơn từ MCP'),
           updated_at = now_ts
     where id = sc.visit_id
     returning id into v_visit_id;
  end if;

  if v_visit_id is null then
    insert into mcp.mcp_visits (
      id, session_id, route_id, route_customer_id, visit_date, status, has_order, has_test, has_report,
      order_id, checkin_at, note, raw_payload, created_at, updated_at
    ) values (
      'mcv_' || replace(gen_random_uuid()::text, '-', ''),
      sc.session_id, sc.route_id, sc.route_customer_id, sess.session_date, 'visited', true, false, false,
      v_order_id, now_ts, coalesce(nullif(p_note, ''), 'Tạo đơn từ MCP'),
      jsonb_build_object('source', 'mcp_create_order_from_session_customer', 'session_customer_id', sc.id, 'order_id', v_order_id), now_ts, now_ts
    ) returning id into v_visit_id;
  end if;

  update mcp.mcp_session_customers
     set visit_status = 'visited',
         status_reason = null,
         visit_id = v_visit_id,
         order_id = v_order_id,
         note = coalesce(nullif(p_note, ''), note),
         updated_at = now_ts
   where id = sc.id;

  perform mcp.mcp_recalc_route_session_counters(sc.session_id);

  return jsonb_build_object(
    'orderId', v_order_id,
    'orderCode', v_order_code,
    'sessionCustomerId', sc.id,
    'visitId', v_visit_id,
    'subtotal', subtotal,
    'discountTotal', discount_total,
    'grandTotal', greatest(subtotal - discount_total, 0),
    'itemCount', item_count
  );
end;
$$;

-- Source: 20260705_mcp_test_from_session_customer_contract.sql
create or replace function mcp.mcp_create_test_from_session_customer(
  p_session_customer_id text,
  p_file_id text default null,
  p_file_title text default null,
  p_results jsonb default '[]'::jsonb,
  p_note text default null,
  p_status text default 'tested'
)
returns jsonb
language plpgsql
set search_path = public
as $$
declare
  sc record;
  sess record;
  v_file_id text;
  v_file_title text;
  v_test_customer_id text;
  v_visit_id text;
  v_test_id text;
  item jsonb;
  v_product_id text;
  v_product_name text;
  v_result_status text;
  v_result_note text;
  result_count integer := 0;
  now_ts timestamptz := now();
begin
  if p_session_customer_id is null or length(trim(p_session_customer_id)) = 0 then
    raise exception 'session_customer_id_required' using errcode = '23514';
  end if;

  if p_results is null or jsonb_typeof(p_results) <> 'array' or jsonb_array_length(p_results) = 0 then
    raise exception 'test_results_required' using errcode = '23514';
  end if;

  select * into sc
    from mcp.mcp_session_customers
   where id = p_session_customer_id;

  if sc.id is null then
    raise exception 'session_customer_not_found' using errcode = '23503';
  end if;

  select * into sess
    from mcp.mcp_route_sessions
   where id = sc.session_id;

  if sess.id is null then
    raise exception 'session_not_found' using errcode = '23503';
  end if;

  v_file_id := nullif(trim(coalesce(p_file_id, '')), '');

  if v_file_id is not null then
    select id, title into v_file_id, v_file_title
      from mcp.test_files
     where id = v_file_id
       and deleted_at is null;

    if v_file_id is null then
      raise exception 'test_file_not_found' using errcode = '23503';
    end if;
  else
    v_file_id := 'test_file_' || replace(gen_random_uuid()::text, '-', '');
    v_file_title := coalesce(nullif(trim(coalesce(p_file_title, '')), ''), 'MCP Test - ' || sc.customer_name || ' - ' || sess.session_date::text);

    insert into mcp.test_files (
      id, title, test_date, sales, note, status, sync_status, raw_payload, created_at, updated_at
    ) values (
      v_file_id, v_file_title, sess.session_date, sess.sales, p_note, 'active', 'synced',
      jsonb_build_object('source', 'mcp_create_test_from_session_customer', 'session_id', sc.session_id, 'session_customer_id', sc.id, 'route_id', sc.route_id),
      now_ts, now_ts
    );
  end if;

  select id into v_test_customer_id
    from mcp.test_customers
   where file_id = v_file_id
     and deleted_at is null
     and raw_payload ->> 'session_customer_id' = sc.id
   order by created_at asc
   limit 1;

  if v_test_customer_id is null then
    v_test_customer_id := 'test_customer_' || replace(gen_random_uuid()::text, '-', '');
    insert into mcp.test_customers (
      id, file_id, customer_name, phone, area, status, note, sync_status, raw_payload, created_at, updated_at
    ) values (
      v_test_customer_id, v_file_id, sc.customer_name, sc.phone, sc.area, coalesce(nullif(trim(coalesce(p_status, '')), ''), 'tested'), p_note, 'synced',
      jsonb_build_object('source', 'mcp_create_test_from_session_customer', 'session_id', sc.session_id, 'session_customer_id', sc.id, 'route_customer_id', sc.route_customer_id, 'customer_id', sc.customer_id),
      now_ts, now_ts
    );
  else
    update mcp.test_customers
       set status = coalesce(nullif(trim(coalesce(p_status, '')), ''), status, 'tested'),
           note = coalesce(nullif(trim(coalesce(p_note, '')), ''), note),
           updated_at = now_ts
     where id = v_test_customer_id;
  end if;

  for item in select value from jsonb_array_elements(p_results) loop
    v_product_id := nullif(trim(coalesce(item ->> 'productId', item ->> 'product_id', '')), '');
    v_product_name := nullif(trim(coalesce(item ->> 'productName', item ->> 'product_name', '')), '');

    if v_product_id is not null then
      select product_name into v_product_name
        from mcp.test_file_products
       where id = v_product_id
         and file_id = v_file_id
         and deleted_at is null;

      if v_product_name is null then
        raise exception 'test_product_not_found' using errcode = '23503';
      end if;
    else
      if v_product_name is null then
        raise exception 'product_name_required' using errcode = '23514';
      end if;

      select id into v_product_id
        from mcp.test_file_products
       where file_id = v_file_id
         and deleted_at is null
         and lower(product_name) = lower(v_product_name)
       order by sort_order asc, created_at asc
       limit 1;

      if v_product_id is null then
        v_product_id := 'test_product_' || replace(gen_random_uuid()::text, '-', '');
        insert into mcp.test_file_products (
          id, file_id, product_name, sort_order, status, sync_status, raw_payload, created_at, updated_at
        ) values (
          v_product_id, v_file_id, v_product_name, result_count + 1, 'active', 'synced',
          jsonb_build_object('source', 'mcp_create_test_from_session_customer', 'session_customer_id', sc.id),
          now_ts, now_ts
        );
      end if;
    end if;

    v_result_status := coalesce(nullif(trim(coalesce(item ->> 'status', '')), ''), coalesce(nullif(trim(coalesce(p_status, '')), ''), 'tested'));
    v_result_note := nullif(trim(coalesce(item ->> 'note', '')), '');

    insert into mcp.test_customer_results (
      id, file_id, customer_id, product_id, product_name, status, note, sync_status, raw_payload, created_at, updated_at
    ) values (
      'test_result_' || replace(gen_random_uuid()::text, '-', ''),
      v_file_id, v_test_customer_id, v_product_id, v_product_name, v_result_status, v_result_note,
      'synced', item || jsonb_build_object('source', 'mcp_create_test_from_session_customer', 'session_customer_id', sc.id), now_ts, now_ts
    ) returning id into v_test_id;

    result_count := result_count + 1;
  end loop;

  if result_count = 0 or v_test_id is null then
    raise exception 'test_results_required' using errcode = '23514';
  end if;

  if sc.visit_id is not null then
    update mcp.mcp_visits
       set has_test = true,
           test_id = v_test_id,
           status = 'visited',
           note = coalesce(nullif(trim(coalesce(p_note, '')), ''), note, 'Tạo test từ MCP'),
           updated_at = now_ts
     where id = sc.visit_id
     returning id into v_visit_id;
  end if;

  if v_visit_id is null then
    insert into mcp.mcp_visits (
      id, session_id, route_id, route_customer_id, visit_date, status, has_order, has_test, has_report,
      test_id, checkin_at, note, raw_payload, created_at, updated_at
    ) values (
      'mcv_' || replace(gen_random_uuid()::text, '-', ''),
      sc.session_id, sc.route_id, sc.route_customer_id, sess.session_date, 'visited', false, true, false,
      v_test_id, now_ts, coalesce(nullif(trim(coalesce(p_note, '')), ''), 'Tạo test từ MCP'),
      jsonb_build_object('source', 'mcp_create_test_from_session_customer', 'session_customer_id', sc.id, 'test_id', v_test_id, 'file_id', v_file_id), now_ts, now_ts
    ) returning id into v_visit_id;
  end if;

  update mcp.mcp_session_customers
     set visit_status = 'visited',
         status_reason = null,
         visit_id = v_visit_id,
         test_id = v_test_id,
         note = coalesce(nullif(trim(coalesce(p_note, '')), ''), note),
         updated_at = now_ts
   where id = sc.id;

  perform mcp.mcp_recalc_route_session_counters(sc.session_id);

  return jsonb_build_object(
    'fileId', v_file_id,
    'fileTitle', v_file_title,
    'testCustomerId', v_test_customer_id,
    'testId', v_test_id,
    'resultCount', result_count,
    'sessionCustomerId', sc.id,
    'visitId', v_visit_id
  );
end;
$$;

-- Source: 20260705_mcp_report_from_session_customer_contract.sql
create or replace function mcp.mcp_create_report_from_session_customer(
  p_session_customer_id text,
  p_report_type text default 'general',
  p_content text default null,
  p_price_summary text default null,
  p_competitor_summary text default null,
  p_display_summary text default null,
  p_stock_summary text default null,
  p_demand_summary text default null,
  p_opportunity_summary text default null,
  p_risk_summary text default null,
  p_next_action text default null,
  p_note text default null
)
returns jsonb
language plpgsql
set search_path = public
as $$
declare
  sc record;
  sess record;
  v_report_id text;
  v_visit_id text;
  v_report_type text;
  v_company_summary text;
  v_note text;
  now_ts timestamptz := now();
begin
  if p_session_customer_id is null or length(trim(p_session_customer_id)) = 0 then
    raise exception 'session_customer_id_required' using errcode = '23514';
  end if;

  v_report_type := coalesce(nullif(trim(coalesce(p_report_type, '')), ''), 'general');
  v_note := coalesce(nullif(trim(coalesce(p_content, '')), ''), nullif(trim(coalesce(p_note, '')), ''));

  if v_note is null
     and nullif(trim(coalesce(p_price_summary, '')), '') is null
     and nullif(trim(coalesce(p_competitor_summary, '')), '') is null
     and nullif(trim(coalesce(p_display_summary, '')), '') is null
     and nullif(trim(coalesce(p_stock_summary, '')), '') is null
     and nullif(trim(coalesce(p_demand_summary, '')), '') is null
     and nullif(trim(coalesce(p_opportunity_summary, '')), '') is null
     and nullif(trim(coalesce(p_risk_summary, '')), '') is null
     and nullif(trim(coalesce(p_next_action, '')), '') is null then
    raise exception 'report_content_required' using errcode = '23514';
  end if;

  select * into sc
    from mcp.mcp_session_customers
   where id = p_session_customer_id;

  if sc.id is null then
    raise exception 'session_customer_not_found' using errcode = '23503';
  end if;

  select * into sess
    from mcp.mcp_route_sessions
   where id = sc.session_id;

  if sess.id is null then
    raise exception 'session_not_found' using errcode = '23503';
  end if;

  v_company_summary := concat_ws(E'\n',
    nullif(trim(coalesce(p_display_summary, '')), ''),
    nullif(trim(coalesce(p_stock_summary, '')), '')
  );
  if v_company_summary = '' then
    v_company_summary := null;
  end if;

  v_report_id := 'report_' || replace(gen_random_uuid()::text, '-', '');

  insert into mcp.market_reports (
    id, report_date, sales, market_area, route_name, market_type, total_shops,
    competitor_summary, price_summary, demand_summary, company_product_summary,
    opportunity_summary, risk_summary, next_action, note, sync_status, raw_payload,
    created_at, updated_at
  ) values (
    v_report_id, sess.session_date, sess.sales, coalesce(sc.area, sess.area), sess.route_name, v_report_type, 1,
    nullif(trim(coalesce(p_competitor_summary, '')), ''),
    nullif(trim(coalesce(p_price_summary, '')), ''),
    nullif(trim(coalesce(p_demand_summary, '')), ''),
    v_company_summary,
    nullif(trim(coalesce(p_opportunity_summary, '')), ''),
    nullif(trim(coalesce(p_risk_summary, '')), ''),
    nullif(trim(coalesce(p_next_action, '')), ''),
    v_note,
    'synced',
    jsonb_build_object(
      'source', 'mcp_create_report_from_session_customer',
      'session_id', sc.session_id,
      'session_customer_id', sc.id,
      'route_id', sc.route_id,
      'route_customer_id', sc.route_customer_id,
      'customer_id', sc.customer_id,
      'report_type', v_report_type,
      'display_summary', nullif(trim(coalesce(p_display_summary, '')), ''),
      'stock_summary', nullif(trim(coalesce(p_stock_summary, '')), '')
    ),
    now_ts, now_ts
  );

  if sc.visit_id is not null then
    update mcp.mcp_visits
       set has_report = true,
           report_id = v_report_id,
           status = 'visited',
           note = coalesce(v_note, note, 'Tao bao cao tu MCP'),
           updated_at = now_ts
     where id = sc.visit_id
     returning id into v_visit_id;
  end if;

  if v_visit_id is null then
    insert into mcp.mcp_visits (
      id, session_id, route_id, route_customer_id, visit_date, status, has_order, has_test, has_report,
      report_id, checkin_at, note, raw_payload, created_at, updated_at
    ) values (
      'mcv_' || replace(gen_random_uuid()::text, '-', ''),
      sc.session_id, sc.route_id, sc.route_customer_id, sess.session_date, 'visited', false, false, true,
      v_report_id, now_ts, coalesce(v_note, 'Tao bao cao tu MCP'),
      jsonb_build_object('source', 'mcp_create_report_from_session_customer', 'session_customer_id', sc.id, 'report_id', v_report_id),
      now_ts, now_ts
    ) returning id into v_visit_id;
  end if;

  update mcp.mcp_session_customers
     set visit_status = 'visited',
         status_reason = null,
         visit_id = v_visit_id,
         report_id = v_report_id,
         note = coalesce(v_note, note),
         updated_at = now_ts
   where id = sc.id;

  perform mcp.mcp_recalc_route_session_counters(sc.session_id);

  return jsonb_build_object(
    'reportId', v_report_id,
    'reportType', v_report_type,
    'sessionCustomerId', sc.id,
    'visitId', v_visit_id
  );
end;
$$;

-- Source: 20260705_mcp_followup_from_session_customer_contract.sql
create or replace function mcp.mcp_create_followup_from_session_customer(
  p_session_customer_id text,
  p_title text,
  p_due_date date default null,
  p_priority text default 'medium',
  p_owner text default null,
  p_note text default null,
  p_followup_type text default 'general'
)
returns jsonb
language plpgsql
set search_path = public
as $$
declare
  sc record;
  v_followup_id text;
  v_priority text;
  v_title text;
  v_followup_type text;
  v_count integer := 0;
  now_ts timestamptz := now();
begin
  if p_session_customer_id is null or length(trim(p_session_customer_id)) = 0 then
    raise exception 'session_customer_id_required' using errcode = '23514';
  end if;

  v_title := nullif(trim(coalesce(p_title, '')), '');
  if v_title is null then
    raise exception 'followup_title_required' using errcode = '23514';
  end if;

  v_priority := lower(coalesce(nullif(trim(coalesce(p_priority, '')), ''), 'medium'));
  if v_priority not in ('low', 'medium', 'high', 'urgent') then
    raise exception 'invalid_priority' using errcode = '23514';
  end if;

  v_followup_type := lower(coalesce(nullif(trim(coalesce(p_followup_type, '')), ''), 'general'));

  select * into sc
    from mcp.mcp_session_customers
   where id = p_session_customer_id;

  if sc.id is null then
    raise exception 'session_customer_not_found' using errcode = '23503';
  end if;

  v_followup_id := 'mcf_' || replace(gen_random_uuid()::text, '-', '');

  insert into mcp.mcp_followups (
    id, session_id, session_customer_id, visit_id, route_id, route_customer_id,
    customer_id, customer_name, followup_type, title, due_date, status, priority,
    owner, note, raw_payload, created_at, updated_at
  ) values (
    v_followup_id, sc.session_id, sc.id, sc.visit_id, sc.route_id, sc.route_customer_id,
    sc.customer_id, sc.customer_name, v_followup_type, v_title, p_due_date, 'open', v_priority,
    nullif(trim(coalesce(p_owner, '')), ''), nullif(trim(coalesce(p_note, '')), ''),
    jsonb_build_object('source', 'mcp_create_followup_from_session_customer', 'session_customer_id', sc.id),
    now_ts, now_ts
  );

  select count(*)::integer into v_count
    from mcp.mcp_followups
   where session_customer_id = sc.id
     and status = 'open';

  update mcp.mcp_session_customers
     set followup_count = v_count,
         updated_at = now_ts
   where id = sc.id;

  perform mcp.mcp_recalc_route_session_counters(sc.session_id);

  return jsonb_build_object(
    'followupId', v_followup_id,
    'sessionCustomerId', sc.id,
    'followupCount', v_count
  );
end;
$$;

-- Source: 20260712025937_freeze_mcp_v1_contract_20260711.sql
create or replace function mcp.mcp_create_session_report_snapshot(
  p_session_id text,
  p_source text default 'close_session'
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $function$
declare
  v_source jsonb;
  v_session jsonb;
  v_customers jsonb;
  v_reports jsonb;
  v_orders jsonb;
  v_tests jsonb;
  v_followups jsonb;
  v_overview jsonb;
  v_sections jsonb;
  v_kpis jsonb;
  v_planned integer;
  v_visited integer;
  v_skipped integer;
  v_pending integer;
  v_score integer;
  v_health text;
  v_now timestamptz := now();
  v_row mcp.mcp_session_reports%rowtype;
begin
  if nullif(btrim(coalesce(p_session_id, '')), '') is null then
    raise exception 'session_id_required' using errcode = '23514';
  end if;

  perform mcp.mcp_recalc_route_session_counters(p_session_id);
  v_source := mcp.mcp_get_session_report_source(p_session_id, null, null);
  v_session := v_source -> 'session';
  if v_session is null or v_session = 'null'::jsonb then
    raise exception 'session_not_found' using errcode = '23503';
  end if;

  v_customers := coalesce(v_source -> 'customers', '[]'::jsonb);
  v_reports := coalesce(v_source -> 'reports', '[]'::jsonb);
  v_orders := coalesce(v_source -> 'orders', '[]'::jsonb);
  v_tests := coalesce(v_source -> 'tests', '[]'::jsonb);
  v_followups := coalesce(v_source -> 'followups', '[]'::jsonb);

  v_planned := jsonb_array_length(v_customers);
  select count(*)::integer,
         count(*) filter (where coalesce(value ->> 'visit_status', 'pending') in ('skipped', 'cancelled'))::integer
    into v_visited, v_skipped
    from jsonb_array_elements(v_customers)
   where coalesce(value ->> 'visit_status', 'pending') in ('visited', 'skipped', 'cancelled');
  select count(*)::integer into v_visited
    from jsonb_array_elements(v_customers)
   where coalesce(value ->> 'visit_status', 'pending') = 'visited';
  v_pending := greatest(v_planned - v_visited - v_skipped, 0);

  v_overview := jsonb_build_object(
    'planned', v_planned,
    'visited', v_visited,
    'pending', v_pending,
    'skipped', v_skipped,
    'observations', jsonb_array_length(v_reports),
    'orders', jsonb_array_length(v_orders),
    'tests', jsonb_array_length(v_tests),
    'followups', jsonb_array_length(v_followups)
  );

  v_kpis := jsonb_build_array(
    jsonb_build_object('label', 'Khách', 'value', v_planned, 'hint', v_visited || ' đã ghé · ' || v_pending || ' chờ'),
    jsonb_build_object('label', 'Quan sát', 'value', jsonb_array_length(v_reports), 'hint', 'Input cho BC phiên'),
    jsonb_build_object('label', 'Đơn/Test', 'value', jsonb_array_length(v_orders) || '/' || jsonb_array_length(v_tests), 'hint', 'Trong phiên'),
    jsonb_build_object('label', 'Follow-up', 'value', jsonb_array_length(v_followups), 'hint', v_skipped || ' bỏ qua')
  );

  v_sections := jsonb_build_object(
    'overview', v_overview,
    'observations', v_reports,
    'orders', v_orders,
    'tests', v_tests,
    'followups', v_followups,
    'customers', v_customers
  );

  v_score := case when v_planned = 0 then 0 else least(100,
    round((v_visited::numeric / v_planned::numeric) * 70)::integer
    + least(30, (jsonb_array_length(v_orders) + jsonb_array_length(v_tests) + jsonb_array_length(v_reports) + jsonb_array_length(v_followups)) * 5)
  ) end;
  v_health := case when v_score >= 80 then 'good' when v_score >= 50 then 'watch' else 'risk' end;

  insert into mcp.mcp_session_reports (
    session_id, route_id, route_name, session_date, sales, status, snapshot_source,
    schema_version, kpis, overview, sections, customer_details, insights, score,
    health, warnings, recommended_actions, ai_prompt_context, summary_text,
    raw_payload, snapshot_at, updated_at
  ) values (
    p_session_id,
    v_session ->> 'route_id',
    v_session ->> 'route_name',
    (v_session ->> 'session_date')::date,
    v_session ->> 'sales',
    'snapshot',
    coalesce(nullif(btrim(coalesce(p_source, '')), ''), 'close_session'),
    'mcp.session-report.snapshot.v2',
    v_kpis,
    v_overview,
    v_sections,
    v_customers,
    jsonb_build_object('summary', case when v_health = 'good' then 'Phiên có độ phủ tốt.' when v_health = 'watch' then 'Phiên cần theo dõi thêm.' else 'Phiên có độ phủ hoặc dữ liệu thấp.' end),
    v_score,
    v_health,
    case when v_pending > 0 then jsonb_build_array('Còn ' || v_pending || ' khách chưa xử lý trong phiên.') else '[]'::jsonb end,
    case when v_pending > 0 then jsonb_build_array(jsonb_build_object('type', 'route_coverage', 'priority', 'high', 'action', 'Rà lại khách chưa xử lý.')) else '[]'::jsonb end,
    jsonb_build_object('task', 'mcp_session_report_analysis', 'source', v_source),
    'BC phiên ' || coalesce(v_session ->> 'route_name', v_session ->> 'route_id') || ' - ' || (v_session ->> 'session_date'),
    jsonb_build_object('source', v_source, 'overview', v_overview, 'sections', v_sections),
    v_now,
    v_now
  )
  on conflict (session_id) do update set
    route_id = excluded.route_id,
    route_name = excluded.route_name,
    session_date = excluded.session_date,
    sales = excluded.sales,
    status = excluded.status,
    snapshot_source = excluded.snapshot_source,
    schema_version = excluded.schema_version,
    kpis = excluded.kpis,
    overview = excluded.overview,
    sections = excluded.sections,
    customer_details = excluded.customer_details,
    insights = excluded.insights,
    score = excluded.score,
    health = excluded.health,
    warnings = excluded.warnings,
    recommended_actions = excluded.recommended_actions,
    ai_prompt_context = excluded.ai_prompt_context,
    summary_text = excluded.summary_text,
    raw_payload = excluded.raw_payload,
    snapshot_at = excluded.snapshot_at,
    updated_at = excluded.updated_at
  returning * into v_row;

  return to_jsonb(v_row);
end;
$function$;

-- Source: 20260716193000_save_session_report_ai_result.sql
create or replace function mcp.mcp_save_session_report_ai_result(
  p_session_id text,
  p_ai_result jsonb,
  p_analyzed_at timestamptz default null,
  p_context jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $function$
declare
  v_report mcp.mcp_session_reports%rowtype;
  v_analyzed_at timestamptz := coalesce(p_analyzed_at, now());
begin
  if nullif(btrim(coalesce(p_session_id, '')), '') is null then
    raise exception 'session_id_required' using errcode = '23514';
  end if;

  if p_ai_result is null then
    raise exception 'ai_result_required' using errcode = '23514';
  end if;

  if jsonb_typeof(p_ai_result) <> 'object' then
    raise exception 'invalid_ai_result' using errcode = '23514';
  end if;

  select *
    into v_report
    from mcp.mcp_session_reports
   where session_id = p_session_id
   for update;

  if not found then
    raise exception 'session_report_not_found' using errcode = '23503';
  end if;

  update mcp.mcp_session_reports
     set ai_result = p_ai_result,
         ai_analyzed_at = v_analyzed_at,
         raw_payload = jsonb_set(
           coalesce(raw_payload, '{}'::jsonb),
           '{aiResultContext}',
           coalesce(p_context, '{}'::jsonb),
           true
         ),
         updated_at = v_analyzed_at
   where id = v_report.id
   returning * into v_report;

  return jsonb_build_object(
    'row', to_jsonb(v_report),
    'analyzedAt', v_analyzed_at
  );
end;
$function$;

-- Source: 20260716234500_field_check_mutation_owner.sql
create or replace function mcp.mcp_update_field_check_result(
  p_result_id text,
  p_product_id text,
  p_product_name text,
  p_status text,
  p_note text,
  p_session_customer_id text,
  p_input_meta jsonb,
  p_context jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $function$
declare
  v_existing mcp.test_customer_results%rowtype;
  v_updated mcp.test_customer_results%rowtype;
  v_product_name text;
  v_status text;
  v_input_meta jsonb;
begin
  if p_result_id is null or length(trim(p_result_id)) = 0 then
    raise exception 'result_id_required' using errcode = '23514';
  end if;

  v_product_name := nullif(trim(coalesce(p_product_name, '')), '');
  if v_product_name is null then
    raise exception 'product_name_required' using errcode = '23514';
  end if;
  if length(v_product_name) > 500 then
    raise exception 'invalid_product_name' using errcode = '23514';
  end if;

  v_status := lower(trim(coalesce(p_status, '')));
  if v_status not in ('ok', 'interested', 'bad') then
    raise exception 'invalid_field_check_status' using errcode = '23514';
  end if;

  if p_note is not null and length(p_note) > 5000 then
    raise exception 'invalid_note' using errcode = '23514';
  end if;

  if p_product_id is not null and length(p_product_id) > 200 then
    raise exception 'invalid_product_id' using errcode = '23514';
  end if;

  select *
    into v_existing
    from mcp.test_customer_results
   where id = trim(p_result_id)
     and deleted_at is null
   for update;

  if v_existing.id is null then
    raise exception 'field_check_result_not_found' using errcode = 'P0002';
  end if;

  if p_session_customer_id is not null
     and length(trim(p_session_customer_id)) > 0
     and not exists (
       select 1
         from mcp.mcp_session_customers sc
        where sc.id = trim(p_session_customer_id)
          and (
            sc.test_id = v_existing.id
            or v_existing.raw_payload ->> 'session_customer_id' = sc.id
          )
     ) then
    raise exception 'field_check_session_customer_mismatch' using errcode = '23514';
  end if;

  v_input_meta := jsonb_strip_nulls(coalesce(p_input_meta, '{}'::jsonb));

  update mcp.test_customer_results
     set product_id = nullif(trim(coalesce(p_product_id, '')), ''),
         product_name = v_product_name,
         status = v_status,
         note = nullif(trim(coalesce(p_note, '')), ''),
         sync_status = 'pending',
         raw_payload = coalesce(v_existing.raw_payload, '{}'::jsonb)
           || jsonb_build_object(
             'field_check_update', v_input_meta,
             'foundation_context', coalesce(p_context, '{}'::jsonb)
           ),
         updated_at = now()
   where id = v_existing.id
   returning * into v_updated;

  return to_jsonb(v_updated);
end;
$function$;

-- Source: 20260716213000_report_setting_mutations.sql
create or replace function mcp.mcp_create_report_setting_group(
  p_group_key text,
  p_title text,
  p_group_type text default 'market_report',
  p_description text default null,
  p_sort_order integer default 0,
  p_status text default 'active',
  p_meta jsonb default '{}'::jsonb,
  p_context jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $function$
declare
  v_group mcp.mcp_setting_groups%rowtype;
  v_group_key text := lower(btrim(coalesce(p_group_key, '')));
  v_title text := btrim(coalesce(p_title, ''));
  v_group_type text := lower(btrim(coalesce(p_group_type, 'market_report')));
  v_description text := nullif(btrim(coalesce(p_description, '')), '');
  v_status text := lower(btrim(coalesce(p_status, 'active')));
begin
  if v_group_key = '' or length(v_group_key) > 120 or v_group_key !~ '^[a-z0-9]+(_[a-z0-9]+)*$' then
    raise exception 'invalid_group_key' using errcode = '23514';
  end if;
  if v_title = '' then
    raise exception 'title_required' using errcode = '23514';
  end if;
  if length(v_title) > 200 then
    raise exception 'invalid_title' using errcode = '23514';
  end if;
  if v_group_type !~ '^[a-z][a-z0-9_]{0,63}$' then
    raise exception 'invalid_group_type' using errcode = '23514';
  end if;
  if v_status not in ('active', 'inactive') then
    raise exception 'invalid_setting_status' using errcode = '23514';
  end if;
  if p_sort_order < 0 or p_sort_order > 100000 then
    raise exception 'invalid_sort_order' using errcode = '23514';
  end if;
  if jsonb_typeof(coalesce(p_meta, '{}'::jsonb)) <> 'object' then
    raise exception 'invalid_meta' using errcode = '23514';
  end if;
  if jsonb_typeof(coalesce(p_context, '{}'::jsonb)) <> 'object' then
    raise exception 'invalid_context' using errcode = '23514';
  end if;

  begin
    insert into mcp.mcp_setting_groups (
      group_key,
      title,
      group_type,
      description,
      sort_order,
      status,
      raw_payload
    ) values (
      v_group_key,
      v_title,
      v_group_type,
      v_description,
      p_sort_order,
      v_status,
      coalesce(p_meta, '{}'::jsonb)
        || jsonb_build_object('foundation_context', coalesce(p_context, '{}'::jsonb))
    )
    returning * into v_group;
  exception
    when unique_violation then
      raise exception 'report_setting_group_key_conflict' using errcode = '23505';
  end;

  return to_jsonb(v_group);
end;
$function$;

-- Source: 20260716213000_report_setting_mutations.sql
create or replace function mcp.mcp_update_report_setting_group(
  p_group_id text,
  p_patch jsonb,
  p_context jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $function$
declare
  v_group mcp.mcp_setting_groups%rowtype;
  v_group_key text;
  v_title text;
  v_sort_order integer;
  v_status text;
begin
  if nullif(btrim(coalesce(p_group_id, '')), '') is null then
    raise exception 'group_id_required' using errcode = '23514';
  end if;
  if p_patch is null or jsonb_typeof(p_patch) <> 'object' or p_patch = '{}'::jsonb then
    raise exception 'report_setting_patch_required' using errcode = '23514';
  end if;
  if exists (
    select 1
      from jsonb_object_keys(p_patch) as keys(key)
     where key not in ('group_key', 'title', 'description', 'sort_order', 'status', 'meta')
  ) then
    raise exception 'invalid_report_setting_group_patch' using errcode = '23514';
  end if;
  if jsonb_typeof(coalesce(p_context, '{}'::jsonb)) <> 'object' then
    raise exception 'invalid_context' using errcode = '23514';
  end if;

  select *
    into v_group
    from mcp.mcp_setting_groups
   where id = p_group_id
   for update;

  if not found then
    raise exception 'report_setting_group_not_found' using errcode = '23503';
  end if;

  if p_patch ? 'group_key' then
    v_group_key := lower(btrim(coalesce(p_patch->>'group_key', '')));
    if v_group_key = '' or length(v_group_key) > 120 or v_group_key !~ '^[a-z0-9]+(_[a-z0-9]+)*$' then
      raise exception 'invalid_group_key' using errcode = '23514';
    end if;
  end if;

  if p_patch ? 'title' then
    v_title := btrim(coalesce(p_patch->>'title', ''));
    if v_title = '' then
      raise exception 'title_required' using errcode = '23514';
    end if;
    if length(v_title) > 200 then
      raise exception 'invalid_title' using errcode = '23514';
    end if;
  end if;

  if p_patch ? 'sort_order' then
    begin
      v_sort_order := (p_patch->>'sort_order')::integer;
    exception
      when invalid_text_representation or numeric_value_out_of_range then
        raise exception 'invalid_sort_order' using errcode = '23514';
    end;
    if v_sort_order < 0 or v_sort_order > 100000 then
      raise exception 'invalid_sort_order' using errcode = '23514';
    end if;
  end if;

  if p_patch ? 'status' then
    v_status := lower(btrim(coalesce(p_patch->>'status', '')));
    if v_status not in ('active', 'inactive') then
      raise exception 'invalid_setting_status' using errcode = '23514';
    end if;
  end if;

  if p_patch ? 'meta' and jsonb_typeof(p_patch->'meta') <> 'object' then
    raise exception 'invalid_meta' using errcode = '23514';
  end if;

  begin
    update mcp.mcp_setting_groups
       set group_key = case when p_patch ? 'group_key' then v_group_key else v_group.group_key end,
           title = case when p_patch ? 'title' then v_title else v_group.title end,
           description = case
             when p_patch ? 'description' then nullif(btrim(coalesce(p_patch->>'description', '')), '')
             else v_group.description
           end,
           sort_order = case when p_patch ? 'sort_order' then v_sort_order else v_group.sort_order end,
           status = case when p_patch ? 'status' then v_status else v_group.status end,
           raw_payload = coalesce(v_group.raw_payload, '{}'::jsonb)
             || case when p_patch ? 'meta' then p_patch->'meta' else '{}'::jsonb end
             || jsonb_build_object('foundation_context', coalesce(p_context, '{}'::jsonb)),
           updated_at = now()
     where id = v_group.id
     returning * into v_group;
  exception
    when unique_violation then
      raise exception 'report_setting_group_key_conflict' using errcode = '23505';
  end;

  return to_jsonb(v_group);
end;
$function$;

-- Source: 20260716213000_report_setting_mutations.sql
create or replace function mcp.mcp_create_report_setting_item(
  p_group_id text,
  p_item_key text,
  p_label text,
  p_value text default null,
  p_category text default null,
  p_brand_name text default null,
  p_product_id text default null,
  p_sort_order integer default 0,
  p_status text default 'active',
  p_meta jsonb default '{}'::jsonb,
  p_context jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $function$
declare
  v_item mcp.mcp_setting_items%rowtype;
  v_item_key text := lower(btrim(coalesce(p_item_key, '')));
  v_label text := btrim(coalesce(p_label, ''));
  v_value text := nullif(btrim(coalesce(p_value, '')), '');
  v_category text := nullif(btrim(coalesce(p_category, '')), '');
  v_brand_name text := nullif(btrim(coalesce(p_brand_name, '')), '');
  v_product_id text := nullif(btrim(coalesce(p_product_id, '')), '');
  v_status text := lower(btrim(coalesce(p_status, 'active')));
begin
  if nullif(btrim(coalesce(p_group_id, '')), '') is null then
    raise exception 'group_id_required' using errcode = '23514';
  end if;
  if v_item_key = '' or length(v_item_key) > 120 or v_item_key !~ '^[a-z0-9]+(_[a-z0-9]+)*$' then
    raise exception 'invalid_item_key' using errcode = '23514';
  end if;
  if v_label = '' then
    raise exception 'label_required' using errcode = '23514';
  end if;
  if length(v_label) > 200 then
    raise exception 'invalid_label' using errcode = '23514';
  end if;
  if v_status not in ('active', 'inactive') then
    raise exception 'invalid_setting_status' using errcode = '23514';
  end if;
  if p_sort_order < 0 or p_sort_order > 100000 then
    raise exception 'invalid_sort_order' using errcode = '23514';
  end if;
  if jsonb_typeof(coalesce(p_meta, '{}'::jsonb)) <> 'object' then
    raise exception 'invalid_meta' using errcode = '23514';
  end if;
  if jsonb_typeof(coalesce(p_context, '{}'::jsonb)) <> 'object' then
    raise exception 'invalid_context' using errcode = '23514';
  end if;

  perform 1
    from mcp.mcp_setting_groups
   where id = p_group_id
   for key share;

  if not found then
    raise exception 'report_setting_group_not_found' using errcode = '23503';
  end if;

  begin
    insert into mcp.mcp_setting_items (
      group_id,
      item_key,
      label,
      value,
      category,
      brand_name,
      product_id,
      sort_order,
      status,
      raw_payload
    ) values (
      p_group_id,
      v_item_key,
      v_label,
      coalesce(v_value, v_label),
      v_category,
      v_brand_name,
      v_product_id,
      p_sort_order,
      v_status,
      coalesce(p_meta, '{}'::jsonb)
        || jsonb_build_object('foundation_context', coalesce(p_context, '{}'::jsonb))
    )
    returning * into v_item;
  exception
    when unique_violation then
      raise exception 'report_setting_item_key_conflict' using errcode = '23505';
    when foreign_key_violation then
      raise exception 'report_setting_product_not_found' using errcode = '23503';
  end;

  return to_jsonb(v_item);
end;
$function$;

-- Source: 20260716213000_report_setting_mutations.sql
create or replace function mcp.mcp_update_report_setting_item(
  p_item_id text,
  p_patch jsonb,
  p_context jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $function$
declare
  v_item mcp.mcp_setting_items%rowtype;
  v_item_key text;
  v_label text;
  v_sort_order integer;
  v_status text;
begin
  if nullif(btrim(coalesce(p_item_id, '')), '') is null then
    raise exception 'item_id_required' using errcode = '23514';
  end if;
  if p_patch is null or jsonb_typeof(p_patch) <> 'object' or p_patch = '{}'::jsonb then
    raise exception 'report_setting_patch_required' using errcode = '23514';
  end if;
  if exists (
    select 1
      from jsonb_object_keys(p_patch) as keys(key)
     where key not in ('item_key', 'label', 'value', 'category', 'brand_name', 'product_id', 'sort_order', 'status', 'meta')
  ) then
    raise exception 'invalid_report_setting_item_patch' using errcode = '23514';
  end if;
  if jsonb_typeof(coalesce(p_context, '{}'::jsonb)) <> 'object' then
    raise exception 'invalid_context' using errcode = '23514';
  end if;

  select *
    into v_item
    from mcp.mcp_setting_items
   where id = p_item_id
   for update;

  if not found then
    raise exception 'report_setting_item_not_found' using errcode = '23503';
  end if;

  if p_patch ? 'item_key' then
    v_item_key := lower(btrim(coalesce(p_patch->>'item_key', '')));
    if v_item_key = '' or length(v_item_key) > 120 or v_item_key !~ '^[a-z0-9]+(_[a-z0-9]+)*$' then
      raise exception 'invalid_item_key' using errcode = '23514';
    end if;
  end if;

  if p_patch ? 'label' then
    v_label := btrim(coalesce(p_patch->>'label', ''));
    if v_label = '' then
      raise exception 'label_required' using errcode = '23514';
    end if;
    if length(v_label) > 200 then
      raise exception 'invalid_label' using errcode = '23514';
    end if;
  end if;

  if p_patch ? 'sort_order' then
    begin
      v_sort_order := (p_patch->>'sort_order')::integer;
    exception
      when invalid_text_representation or numeric_value_out_of_range then
        raise exception 'invalid_sort_order' using errcode = '23514';
    end;
    if v_sort_order < 0 or v_sort_order > 100000 then
      raise exception 'invalid_sort_order' using errcode = '23514';
    end if;
  end if;

  if p_patch ? 'status' then
    v_status := lower(btrim(coalesce(p_patch->>'status', '')));
    if v_status not in ('active', 'inactive') then
      raise exception 'invalid_setting_status' using errcode = '23514';
    end if;
  end if;

  if p_patch ? 'meta' and jsonb_typeof(p_patch->'meta') <> 'object' then
    raise exception 'invalid_meta' using errcode = '23514';
  end if;

  begin
    update mcp.mcp_setting_items
       set item_key = case when p_patch ? 'item_key' then v_item_key else v_item.item_key end,
           label = case when p_patch ? 'label' then v_label else v_item.label end,
           value = case when p_patch ? 'value' then nullif(btrim(coalesce(p_patch->>'value', '')), '') else v_item.value end,
           category = case when p_patch ? 'category' then nullif(btrim(coalesce(p_patch->>'category', '')), '') else v_item.category end,
           brand_name = case when p_patch ? 'brand_name' then nullif(btrim(coalesce(p_patch->>'brand_name', '')), '') else v_item.brand_name end,
           product_id = case when p_patch ? 'product_id' then nullif(btrim(coalesce(p_patch->>'product_id', '')), '') else v_item.product_id end,
           sort_order = case when p_patch ? 'sort_order' then v_sort_order else v_item.sort_order end,
           status = case when p_patch ? 'status' then v_status else v_item.status end,
           raw_payload = coalesce(v_item.raw_payload, '{}'::jsonb)
             || case when p_patch ? 'meta' then p_patch->'meta' else '{}'::jsonb end
             || jsonb_build_object('foundation_context', coalesce(p_context, '{}'::jsonb)),
           updated_at = now()
     where id = v_item.id
     returning * into v_item;
  exception
    when unique_violation then
      raise exception 'report_setting_item_key_conflict' using errcode = '23505';
    when foreign_key_violation then
      raise exception 'report_setting_product_not_found' using errcode = '23503';
  end;

  return to_jsonb(v_item);
end;
$function$;

-- Source: 20260719190000_add_standalone_order_create.sql
create or replace function mcp.mcp_create_order(
  p_customer_mode text,
  p_route_customer_id text,
  p_customer_name text,
  p_customer_phone text,
  p_area text,
  p_delivery_address text,
  p_sales text,
  p_items jsonb,
  p_note text,
  p_status text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $function$
declare
  v_mode text := lower(btrim(coalesce(p_customer_mode, '')));
  v_status text := lower(btrim(coalesce(p_status, 'confirmed')));
  v_customer record;
  v_order_id text := 'order_' || replace(gen_random_uuid()::text, '-', '');
  v_order_code text;
  v_now timestamptz := now();
  v_customer_id text;
  v_customer_name text;
  v_customer_phone text;
  v_area text;
  v_delivery_address text;
  v_route_customer_id text;
  v_route_id text;
  v_route_name text;
  v_sales text := coalesce(nullif(btrim(coalesce(p_sales, '')), ''), 'Sale');
  v_item jsonb;
  v_product_name text;
  v_quantity numeric;
  v_unit_price numeric;
  v_discount numeric;
  v_line_total numeric;
  v_subtotal numeric := 0;
  v_discount_total numeric := 0;
  v_item_count integer := 0;
begin
  if v_mode not in ('existing', 'manual') then
    raise exception 'invalid_customer_mode' using errcode = '23514';
  end if;

  if v_status not in ('draft', 'confirmed') then
    raise exception 'invalid_order_status' using errcode = '23514';
  end if;

  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'order_items_required' using errcode = '23514';
  end if;

  if v_mode = 'existing' then
    if nullif(btrim(coalesce(p_route_customer_id, '')), '') is null then
      raise exception 'route_customer_id_required' using errcode = '23514';
    end if;

    select
      rc.id,
      rc.route_id,
      rc.customer_id,
      rc.customer_name,
      rc.phone,
      rc.area,
      rc.address,
      rc.active,
      r.route_name
    into v_customer
    from mcp.mcp_route_customers rc
    left join mcp.mcp_routes r on r.id = rc.route_id
    where rc.id = btrim(p_route_customer_id)
    for share of rc;

    if v_customer.id is null then
      raise exception 'route_customer_not_found' using errcode = '23503';
    end if;
    if v_customer.active is false then
      raise exception 'route_customer_inactive' using errcode = '23514';
    end if;

    v_route_customer_id := v_customer.id;
    v_route_id := v_customer.route_id;
    v_route_name := coalesce(v_customer.route_name, v_customer.area, 'Khách đã có');
    v_customer_id := coalesce(v_customer.customer_id, v_customer.id);
    v_customer_name := v_customer.customer_name;
    v_customer_phone := v_customer.phone;
    v_area := v_customer.area;
    v_delivery_address := v_customer.address;
  else
    v_customer_name := nullif(btrim(coalesce(p_customer_name, '')), '');
    if v_customer_name is null then
      raise exception 'customer_name_required' using errcode = '23514';
    end if;

    v_customer_phone := nullif(btrim(coalesce(p_customer_phone, '')), '');
    v_area := nullif(btrim(coalesce(p_area, '')), '');
    v_delivery_address := nullif(btrim(coalesce(p_delivery_address, '')), '');
    v_route_name := coalesce(v_area, 'Khách nhập nhanh');
  end if;

  for v_item in select value from jsonb_array_elements(p_items) loop
    v_product_name := nullif(btrim(coalesce(v_item ->> 'productName', v_item ->> 'product_name', '')), '');
    if v_product_name is null then
      raise exception 'product_name_required' using errcode = '23514';
    end if;

    begin
      v_quantity := nullif(coalesce(v_item ->> 'quantity', ''), '')::numeric;
      v_unit_price := coalesce(nullif(v_item ->> 'unitPrice', '')::numeric, nullif(v_item ->> 'unit_price', '')::numeric, 0);
      v_discount := coalesce(nullif(v_item ->> 'discount', '')::numeric, 0);
    exception when invalid_text_representation then
      raise exception 'invalid_order_item_number' using errcode = '23514';
    end;

    if v_quantity is null or v_quantity <= 0 then
      raise exception 'quantity_required' using errcode = '23514';
    end if;
    if v_unit_price < 0 then
      raise exception 'invalid_unit_price' using errcode = '23514';
    end if;
    if v_discount < 0 or v_discount > v_quantity * v_unit_price then
      raise exception 'invalid_discount' using errcode = '23514';
    end if;

    v_subtotal := v_subtotal + v_quantity * v_unit_price;
    v_discount_total := v_discount_total + v_discount;
    v_item_count := v_item_count + 1;
  end loop;

  v_order_code := 'ORD-' || to_char(current_date, 'YYYYMMDD') || '-' || upper(substr(v_order_id, 7, 6));

  insert into mcp.orders (
    id,
    order_code,
    order_date,
    sales,
    customer_id,
    customer_name,
    customer_phone,
    area,
    delivery_address,
    source_type,
    source_id,
    status,
    subtotal,
    discount_total,
    grand_total,
    note,
    sync_status,
    raw_payload,
    created_at,
    updated_at
  ) values (
    v_order_id,
    v_order_code,
    current_date,
    v_sales,
    v_customer_id,
    v_customer_name,
    v_customer_phone,
    v_area,
    v_delivery_address,
    'orders_tab',
    v_route_customer_id,
    v_status,
    v_subtotal,
    v_discount_total,
    greatest(v_subtotal - v_discount_total, 0),
    nullif(btrim(coalesce(p_note, '')), ''),
    'synced',
    jsonb_build_object(
      'source', 'mcp_create_order',
      'customerMode', v_mode,
      'routeCustomerId', v_route_customer_id,
      'routeId', v_route_id,
      'routeName', v_route_name
    ),
    v_now,
    v_now
  );

  for v_item in select value from jsonb_array_elements(p_items) loop
    v_quantity := nullif(coalesce(v_item ->> 'quantity', ''), '')::numeric;
    v_unit_price := coalesce(nullif(v_item ->> 'unitPrice', '')::numeric, nullif(v_item ->> 'unit_price', '')::numeric, 0);
    v_discount := coalesce(nullif(v_item ->> 'discount', '')::numeric, 0);
    v_line_total := greatest(v_quantity * v_unit_price - v_discount, 0);

    insert into mcp.order_items (
      id,
      order_id,
      product_id,
      variant_id,
      product_name,
      sku,
      unit,
      quantity,
      unit_price,
      discount,
      line_total,
      note,
      raw_payload,
      created_at
    ) values (
      'order_item_' || replace(gen_random_uuid()::text, '-', ''),
      v_order_id,
      nullif(coalesce(v_item ->> 'productId', v_item ->> 'product_id'), ''),
      nullif(coalesce(v_item ->> 'variantId', v_item ->> 'variant_id'), ''),
      coalesce(v_item ->> 'productName', v_item ->> 'product_name'),
      nullif(v_item ->> 'sku', ''),
      nullif(v_item ->> 'unit', ''),
      v_quantity,
      v_unit_price,
      v_discount,
      v_line_total,
      nullif(v_item ->> 'note', ''),
      v_item,
      v_now
    );
  end loop;

  return jsonb_build_object(
    'orderId', v_order_id,
    'orderCode', v_order_code,
    'orderDate', current_date,
    'customerMode', v_mode,
    'routeCustomerId', v_route_customer_id,
    'customerName', v_customer_name,
    'routeName', v_route_name,
    'owner', v_sales,
    'status', v_status,
    'subtotal', v_subtotal,
    'discountTotal', v_discount_total,
    'grandTotal', greatest(v_subtotal - v_discount_total, 0),
    'itemCount', v_item_count
  );
end;
$function$;

-- Source: 20260705_mcp_report_context_contract.sql
create or replace function mcp.mcp_get_report_templates(
  p_report_type text default null,
  p_route_id text default null,
  p_customer_id text default null,
  p_route_customer_id text default null
)
returns jsonb
language sql
stable
set search_path = public
as $$
  select coalesce(jsonb_agg(row_to_json(t)::jsonb order by t.rank, t.sort_order, t.title), '[]'::jsonb)
  from (
    select
      id,
      title,
      report_type as "reportType",
      scope_type as "scopeType",
      route_id as "routeId",
      route_customer_id as "routeCustomerId",
      customer_id as "customerId",
      content,
      price_summary as "priceSummary",
      competitor_summary as "competitorSummary",
      display_summary as "displaySummary",
      stock_summary as "stockSummary",
      demand_summary as "demandSummary",
      opportunity_summary as "opportunitySummary",
      risk_summary as "riskSummary",
      next_action as "nextAction",
      sort_order,
      note,
      case scope_type when 'customer' then 1 when 'session' then 2 when 'route' then 3 else 4 end as rank
    from mcp.mcp_report_templates
    where status = 'active'
      and (p_report_type is null or p_report_type = '' or report_type = p_report_type)
      and (
        scope_type = 'global'
        or (scope_type = 'route' and route_id = p_route_id)
        or (scope_type in ('customer','session') and (
          (p_customer_id is not null and customer_id = p_customer_id)
          or (p_route_customer_id is not null and route_customer_id = p_route_customer_id)
        ))
      )
    union all
    select
      id,
      title,
      report_type as "reportType",
      'route_legacy' as "scopeType",
      route_id as "routeId",
      null::text as "routeCustomerId",
      null::text as "customerId",
      content,
      price_summary as "priceSummary",
      competitor_summary as "competitorSummary",
      display_summary as "displaySummary",
      stock_summary as "stockSummary",
      demand_summary as "demandSummary",
      opportunity_summary as "opportunitySummary",
      risk_summary as "riskSummary",
      next_action as "nextAction",
      999 as sort_order,
      note,
      5 as rank
    from mcp.mcp_route_report_templates
    where status = 'active'
      and route_id = p_route_id
      and (p_report_type is null or p_report_type = '' or report_type = p_report_type)
  ) t;
$$;

-- Source: 20260705_mcp_report_context_contract.sql
create or replace function mcp.mcp_get_report_context(p_session_customer_id text)
returns jsonb
language plpgsql
stable
set search_path = public
as $$
declare
  sc record;
  competitors jsonb := '[]'::jsonb;
  products jsonb := '[]'::jsonb;
  templates jsonb := '[]'::jsonb;
begin
  select * into sc from mcp.mcp_session_customers where id = p_session_customer_id;
  if sc.id is null then
    raise exception 'session_customer_not_found' using errcode = '23503';
  end if;

  select coalesce(jsonb_agg(row_to_json(c)::jsonb order by c.sort_order, c."competitorName"), '[]'::jsonb)
    into competitors
  from (
    select id, competitor_name as "competitorName", brand_name as "brandName", category, area, route_id as "routeId", note, sort_order
    from mcp.mcp_competitors
    where status = 'active'
      and (route_id is null or route_id = sc.route_id)
      and (area is null or area = '' or sc.area is null or lower(area) = lower(sc.area))
    limit 50
  ) c;

  select coalesce(jsonb_agg(distinct row_to_json(p)::jsonb), '[]'::jsonb)
    into products
  from (
    select id, product_id as "productId", product_name as "productName", brand_name as "brandName", product_source as "source", note
    from mcp.mcp_customer_products
    where status = 'active'
      and (
        route_customer_id = sc.route_customer_id
        or (sc.customer_id is not null and customer_id = sc.customer_id)
        or (route_id = sc.route_id and customer_id is null and route_customer_id is null)
      )
    union
    select oi.id, oi.product_id as "productId", oi.product_name as "productName", null::text as "brandName", 'bought' as "source", oi.note
    from mcp.order_items oi
    join mcp.orders o on o.id = oi.order_id
    where oi.product_name is not null
      and (
        (sc.customer_id is not null and o.customer_id = sc.customer_id)
        or lower(coalesce(o.customer_name, '')) = lower(coalesce(sc.customer_name, ''))
      )
    union
    select tr.id, tr.product_id as "productId", tr.product_name as "productName", null::text as "brandName", 'tested' as "source", tr.note
    from mcp.test_customer_results tr
    join mcp.test_customers tc on tc.id = tr.customer_id
    where tr.product_name is not null
      and (
        (sc.customer_id is not null and tc.id = sc.customer_id)
        or lower(coalesce(tc.customer_name, '')) = lower(coalesce(sc.customer_name, ''))
      )
    limit 80
  ) p;

  templates := mcp.mcp_get_report_templates(null, sc.route_id, sc.customer_id, sc.route_customer_id);

  return jsonb_build_object(
    'sessionCustomer', jsonb_build_object('id', sc.id, 'sessionId', sc.session_id, 'routeId', sc.route_id, 'routeCustomerId', sc.route_customer_id, 'customerId', sc.customer_id, 'customerName', sc.customer_name, 'area', sc.area),
    'competitors', competitors,
    'usedProducts', products,
    'templates', templates
  );
end;
$$;

-- Source: 20260705_mcp_route_order_template_contract.sql
create or replace function mcp.mcp_save_route_order_template(
  p_route_id text,
  p_title text default 'Mau don hang',
  p_note text default null,
  p_items jsonb default '[]'::jsonb
)
returns jsonb
language plpgsql
set search_path = public
as $$
declare
  r record;
  v_template_id text;
  item jsonb;
  v_product_name text;
  v_quantity numeric;
  v_unit_price numeric;
  v_discount numeric;
  v_sort integer := 0;
  v_item_count integer := 0;
  now_ts timestamptz := now();
begin
  if p_route_id is null or length(trim(p_route_id)) = 0 then
    raise exception 'route_id_required' using errcode = '23514';
  end if;

  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'template_items_required' using errcode = '23514';
  end if;

  select id, route_name into r
    from mcp.mcp_routes
   where id = p_route_id;

  if r.id is null then
    raise exception 'route_not_found' using errcode = '23503';
  end if;

  select id into v_template_id
    from mcp.mcp_route_order_templates
   where route_id = r.id;

  if v_template_id is null then
    v_template_id := 'mcp_order_template_' || replace(gen_random_uuid()::text, '-', '');
    insert into mcp.mcp_route_order_templates (
      id, route_id, title, status, note, raw_payload, created_at, updated_at
    ) values (
      v_template_id,
      r.id,
      coalesce(nullif(trim(coalesce(p_title, '')), ''), 'Mau don hang'),
      'active',
      nullif(trim(coalesce(p_note, '')), ''),
      jsonb_build_object('source', 'mcp_save_route_order_template'),
      now_ts,
      now_ts
    );
  else
    update mcp.mcp_route_order_templates
       set title = coalesce(nullif(trim(coalesce(p_title, '')), ''), title, 'Mau don hang'),
           status = 'active',
           note = nullif(trim(coalesce(p_note, '')), ''),
           updated_at = now_ts
     where id = v_template_id;

    delete from mcp.mcp_route_order_template_items
     where template_id = v_template_id;
  end if;

  for item in select value from jsonb_array_elements(p_items) loop
    v_product_name := nullif(trim(coalesce(item ->> 'productName', item ->> 'product_name', '')), '');
    if v_product_name is null then
      raise exception 'product_name_required' using errcode = '23514';
    end if;

    v_quantity := coalesce(nullif(item ->> 'quantity', '')::numeric, 1);
    v_unit_price := coalesce(nullif(coalesce(item ->> 'unitPrice', item ->> 'unit_price'), '')::numeric, 0);
    v_discount := coalesce(nullif(item ->> 'discount', '')::numeric, 0);

    if v_quantity <= 0 then
      raise exception 'quantity_required' using errcode = '23514';
    end if;
    if v_unit_price < 0 or v_discount < 0 then
      raise exception 'invalid_price_or_discount' using errcode = '23514';
    end if;

    v_sort := v_sort + 1;

    insert into mcp.mcp_route_order_template_items (
      id, template_id, product_id, product_name, sku, unit, quantity, unit_price,
      discount, sort_order, note, raw_payload, created_at, updated_at
    ) values (
      'mcp_order_template_item_' || replace(gen_random_uuid()::text, '-', ''),
      v_template_id,
      nullif(trim(coalesce(item ->> 'productId', item ->> 'product_id', '')), ''),
      v_product_name,
      nullif(trim(coalesce(item ->> 'sku', '')), ''),
      nullif(trim(coalesce(item ->> 'unit', '')), ''),
      v_quantity,
      v_unit_price,
      v_discount,
      v_sort,
      nullif(trim(coalesce(item ->> 'note', '')), ''),
      item || jsonb_build_object('source', 'mcp_save_route_order_template'),
      now_ts,
      now_ts
    );

    v_item_count := v_item_count + 1;
  end loop;

  return jsonb_build_object(
    'templateId', v_template_id,
    'routeId', r.id,
    'routeName', r.route_name,
    'itemCount', v_item_count
  );
end;
$$;

-- Source: 20260705_mcp_route_extra_templates_contract.sql
create or replace function mcp.mcp_save_route_test_template(
  p_route_id text,
  p_title text default 'Mau test san pham',
  p_note text default null,
  p_items jsonb default '[]'::jsonb
)
returns jsonb
language plpgsql
set search_path = public
as $$
declare
  r record;
  v_template_id text;
  item jsonb;
  v_product_name text;
  v_status text;
  v_sort integer := 0;
  v_item_count integer := 0;
  now_ts timestamptz := now();
begin
  if p_route_id is null or length(trim(p_route_id)) = 0 then
    raise exception 'route_id_required' using errcode = '23514';
  end if;
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'test_template_items_required' using errcode = '23514';
  end if;

  select id, route_name into r from mcp.mcp_routes where id = p_route_id;
  if r.id is null then raise exception 'route_not_found' using errcode = '23503'; end if;

  select id into v_template_id from mcp.mcp_route_test_templates where route_id = r.id;
  if v_template_id is null then
    v_template_id := 'mcp_test_template_' || replace(gen_random_uuid()::text, '-', '');
    insert into mcp.mcp_route_test_templates (id, route_id, title, status, note, raw_payload, created_at, updated_at)
    values (v_template_id, r.id, coalesce(nullif(trim(coalesce(p_title, '')), ''), 'Mau test san pham'), 'active', nullif(trim(coalesce(p_note, '')), ''), jsonb_build_object('source','mcp_save_route_test_template'), now_ts, now_ts);
  else
    update mcp.mcp_route_test_templates
       set title = coalesce(nullif(trim(coalesce(p_title, '')), ''), title, 'Mau test san pham'),
           status = 'active', note = nullif(trim(coalesce(p_note, '')), ''), updated_at = now_ts
     where id = v_template_id;
    delete from mcp.mcp_route_test_template_items where template_id = v_template_id;
  end if;

  for item in select value from jsonb_array_elements(p_items) loop
    v_product_name := nullif(trim(coalesce(item ->> 'productName', item ->> 'product_name', '')), '');
    if v_product_name is null then raise exception 'product_name_required' using errcode = '23514'; end if;
    v_status := lower(coalesce(nullif(trim(coalesce(item ->> 'defaultStatus', item ->> 'default_status', '')), ''), 'tested'));
    if v_status not in ('tested','ok','retry','not_suitable','follow_up') then
      raise exception 'invalid_test_status' using errcode = '23514';
    end if;
    v_sort := v_sort + 1;
    insert into mcp.mcp_route_test_template_items (id, template_id, product_id, product_name, default_status, sort_order, note, raw_payload, created_at, updated_at)
    values ('mcp_test_template_item_' || replace(gen_random_uuid()::text, '-', ''), v_template_id, nullif(trim(coalesce(item ->> 'productId', item ->> 'product_id', '')), ''), v_product_name, v_status, v_sort, nullif(trim(coalesce(item ->> 'note','')), ''), item || jsonb_build_object('source','mcp_save_route_test_template'), now_ts, now_ts);
    v_item_count := v_item_count + 1;
  end loop;

  return jsonb_build_object('templateId', v_template_id, 'routeId', r.id, 'routeName', r.route_name, 'itemCount', v_item_count);
end;
$$;

