  select id, route_name into r from mcp.mcp_routes where id = p_route_id;
  if r.id is null then
    raise exception 'route_not_found' using errcode = '23503';
  end if;

  select id into v_template_id
    from mcp.mcp_route_skip_reason_templates
   where route_id = r.id;

  if v_template_id is null then
    v_template_id := 'mcp_skip_reason_template_' || replace(gen_random_uuid()::text, '-', '');
