      v_reason_text,
      v_sort,
      nullif(trim(coalesce(item ->> 'note','')), ''),
      item || jsonb_build_object('source','mcp_save_route_skip_reason_template'),
      now_ts,
      now_ts
    );

    v_item_count := v_item_count + 1;
  end loop;

  return jsonb_build_object(
    'templateId', v_template_id,
    'routeId', r.id,
    'routeName', r.route_name,
    'itemCount', v_item_count
  );
end;
$$;

-- Source: 20260720210000_allow_route_customer_profile_media.sql
create or replace function mcp.mcp_prepare_outlet_media_upload(
  p_installation_id text,
  p_route_customer_id text,
  p_session_id text,
  p_client_upload_id text,
  p_mime_type text,
  p_expected_byte_size bigint,
  p_geo_lat double precision default null,
  p_geo_lng double precision default null,
  p_geo_accuracy double precision default null,
  p_context jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $function$
declare
  v_session mcp.mcp_route_sessions%rowtype;
  v_route_customer mcp.mcp_route_customers%rowtype;
  v_media mcp.mcp_outlet_media%rowtype;
  v_active_media_count integer;
  v_media_id text;
  v_extension text;
  v_object_key text;
begin
  if nullif(btrim(coalesce(p_installation_id, '')), '') is null then
    raise exception 'installation_id_required' using errcode = '23514';
  end if;
  if nullif(btrim(coalesce(p_route_customer_id, '')), '') is null then
    raise exception 'route_customer_id_required' using errcode = '23514';
  end if;
  if nullif(btrim(coalesce(p_client_upload_id, '')), '') is null then
    raise exception 'client_upload_id_required' using errcode = '23514';
  end if;
  if p_mime_type not in ('image/jpeg', 'image/webp', 'image/png') then
    raise exception 'invalid_media_mime_type' using errcode = '23514';
  end if;
  if p_expected_byte_size is null or p_expected_byte_size < 1 or p_expected_byte_size > 5242880 then
    raise exception 'invalid_media_byte_size' using errcode = '23514';
  end if;
  if (p_geo_lat is null) <> (p_geo_lng is null) then
    raise exception 'geo_coordinates_incomplete' using errcode = '23514';
  end if;

  if nullif(btrim(coalesce(p_session_id, '')), '') is not null then
    select * into v_session
      from mcp.mcp_route_sessions
     where id = p_session_id
     for update;
    if not found then raise exception 'session_not_found' using errcode = '23503'; end if;
    perform mcp.mcp_assert_session_mutable(v_session.id);
  end if;

  select * into v_route_customer
    from mcp.mcp_route_customers
   where id = p_route_customer_id
   for update;
  if not found then raise exception 'route_customer_not_found' using errcode = '23503'; end if;

  if nullif(btrim(coalesce(p_session_id, '')), '') is not null
     and v_route_customer.route_id is distinct from v_session.route_id then
    raise exception 'route_customer_route_mismatch' using errcode = '23514';
  end if;

  select * into v_media
    from mcp.mcp_outlet_media
   where installation_id = p_installation_id
     and client_upload_id = p_client_upload_id
   for update;

  if found then
    if v_media.route_customer_id is distinct from p_route_customer_id
       or v_media.session_id is distinct from nullif(btrim(coalesce(p_session_id, '')), '')
       or v_media.mime_type is distinct from p_mime_type
       or v_media.expected_byte_size is distinct from p_expected_byte_size then
      raise exception 'outlet_media_upload_conflict' using errcode = '23505';
    end if;
    return to_jsonb(v_media);
  end if;

  select count(*) into v_active_media_count
    from mcp.mcp_outlet_media
   where installation_id = p_installation_id
     and route_customer_id = p_route_customer_id
     and status in ('pending', 'ready', 'deleting', 'delete_failed');

  if v_active_media_count >= 3 then
    raise exception 'outlet_media_limit_reached' using errcode = '23514';
  end if;

  v_media_id := 'mom_' || replace(gen_random_uuid()::text, '-', '');
  v_extension := case p_mime_type when 'image/webp' then 'webp' when 'image/png' then 'png' else 'jpg' end;
  v_object_key := format(
    'mcp-plan/outlets/%s/%s/%s.%s',
    regexp_replace(p_installation_id, '[^a-zA-Z0-9._-]+', '_', 'g'),
    regexp_replace(p_route_customer_id, '[^a-zA-Z0-9._-]+', '_', 'g'),
    v_media_id,
    v_extension
  );

  insert into mcp.mcp_outlet_media (
    id, installation_id, route_customer_id, session_id, object_key,
    mime_type, expected_byte_size, client_upload_id, captured_by,
    geo_lat, geo_lng, geo_accuracy, raw_payload
  ) values (
    v_media_id, p_installation_id, p_route_customer_id,
    nullif(btrim(coalesce(p_session_id, '')), ''), v_object_key,
    p_mime_type, p_expected_byte_size, p_client_upload_id,
    nullif(btrim(coalesce(p_context ->> 'actorId', '')), ''),
    p_geo_lat, p_geo_lng, p_geo_accuracy,
    jsonb_build_object('foundation_context', coalesce(p_context, '{}'::jsonb))
  ) returning * into v_media;

  return to_jsonb(v_media);
end;
$function$;

-- Source: 20260719153000_add_mcp_outlet_media.sql
create or replace function mcp.mcp_finalize_outlet_media_upload(
  p_media_id text,
  p_etag text,
  p_actual_byte_size bigint,
  p_content_type text,
  p_width integer default null,
  p_height integer default null,
  p_context jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $function$
declare
  v_media mcp.mcp_outlet_media%rowtype;
begin
  select * into v_media
    from mcp.mcp_outlet_media
   where id = p_media_id
   for update;
  if not found then raise exception 'outlet_media_not_found' using errcode = '23503'; end if;

  if v_media.status = 'ready' then return to_jsonb(v_media); end if;
  if v_media.status <> 'pending' then
    raise exception 'outlet_media_not_pending' using errcode = '23514';
  end if;
  if p_content_type is distinct from v_media.mime_type then
    raise exception 'outlet_media_content_type_mismatch' using errcode = '23514';
  end if;
  if p_actual_byte_size is null or p_actual_byte_size < 1 or p_actual_byte_size > 5242880 then
    raise exception 'invalid_media_byte_size' using errcode = '23514';
  end if;

  update mcp.mcp_outlet_media
     set status = 'ready',
         etag = nullif(btrim(coalesce(p_etag, '')), ''),
         actual_byte_size = p_actual_byte_size,
         width = p_width,
         height = p_height,
         raw_payload = coalesce(raw_payload, '{}'::jsonb) || jsonb_build_object(
           'finalized_context', coalesce(p_context, '{}'::jsonb)
         ),
         updated_at = now()
   where id = p_media_id
   returning * into v_media;

  return to_jsonb(v_media);
end;
$function$;

-- Source: 20260719160000_add_outlet_media_deletion_lifecycle.sql
create or replace function mcp.mcp_claim_outlet_media_delete(
  p_installation_id text,
  p_media_id text,
  p_context jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $function$
declare
  v_media mcp.mcp_outlet_media%rowtype;
begin
  if nullif(btrim(coalesce(p_installation_id, '')), '') is null then
    raise exception 'installation_id_required' using errcode = '23514';
  end if;
  if nullif(btrim(coalesce(p_media_id, '')), '') is null then
    raise exception 'media_id_required' using errcode = '23514';
  end if;

  select * into v_media
    from mcp.mcp_outlet_media
   where installation_id = p_installation_id
     and id = p_media_id
   for update;

  if not found then
    raise exception 'outlet_media_not_found' using errcode = '23503';
  end if;

  if v_media.status = 'deleted' then
    return to_jsonb(v_media);
  end if;

  update mcp.mcp_outlet_media
     set status = 'deleting',
         delete_requested_at = coalesce(delete_requested_at, now()),
         delete_attempt_count = delete_attempt_count + 1,
         last_delete_error = null,
         raw_payload = coalesce(raw_payload, '{}'::jsonb) || jsonb_build_object(
           'delete_claim_context', coalesce(p_context, '{}'::jsonb)
         ),
         updated_at = now()
   where id = v_media.id
   returning * into v_media;

  return to_jsonb(v_media);
end;
$function$;

-- Source: 20260719160000_add_outlet_media_deletion_lifecycle.sql
create or replace function mcp.mcp_finish_outlet_media_delete(
  p_installation_id text,
  p_media_id text,
  p_succeeded boolean,
  p_error text default null,
  p_context jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $function$
declare
  v_media mcp.mcp_outlet_media%rowtype;
begin
  select * into v_media
    from mcp.mcp_outlet_media
   where installation_id = p_installation_id
     and id = p_media_id
   for update;

  if not found then
    raise exception 'outlet_media_not_found' using errcode = '23503';
  end if;

  if v_media.status = 'deleted' then
    return to_jsonb(v_media);
  end if;

  update mcp.mcp_outlet_media
     set status = case when coalesce(p_succeeded, false) then 'deleted' else 'delete_failed' end,
         deleted_at = case when coalesce(p_succeeded, false) then now() else deleted_at end,
         last_delete_error = case
           when coalesce(p_succeeded, false) then null
           else left(coalesce(nullif(btrim(p_error), ''), 'r2_delete_failed'), 500)
         end,
         raw_payload = coalesce(raw_payload, '{}'::jsonb) || jsonb_build_object(
           'delete_finish_context', coalesce(p_context, '{}'::jsonb)
         ),
         updated_at = now()
   where id = v_media.id
   returning * into v_media;

  return to_jsonb(v_media);
end;
$function$;

-- Source: 20260719161000_add_outlet_media_delete_jobs.sql
create or replace function mcp.mcp_claim_route_customer_media_delete(
  p_installation_id text,
  p_route_customer_id text,
  p_context jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $function$
declare
  v_route_customer mcp.mcp_route_customers%rowtype;
  v_job mcp.mcp_storage_delete_jobs%rowtype;
  v_media jsonb := '[]'::jsonb;
begin
  if nullif(btrim(coalesce(p_installation_id, '')), '') is null then
    raise exception 'installation_id_required' using errcode = '23514';
  end if;
  if nullif(btrim(coalesce(p_route_customer_id, '')), '') is null then
    raise exception 'route_customer_id_required' using errcode = '23514';
  end if;

  select * into v_route_customer
    from mcp.mcp_route_customers
   where id = p_route_customer_id
   for update;

  if not found then
    raise exception 'route_customer_not_found' using errcode = '23503';
  end if;

  insert into mcp.mcp_storage_delete_jobs (
    id, installation_id, target_type, target_id, status, requested_by, raw_payload
  ) values (
    'msdj_' || replace(gen_random_uuid()::text, '-', ''),
    p_installation_id,
    'route_customer',
    v_route_customer.id,
    'pending',
    nullif(btrim(coalesce(p_context ->> 'actorId', '')), ''),
    jsonb_build_object('request_context', coalesce(p_context, '{}'::jsonb))
  )
  on conflict (installation_id, target_type, target_id)
  do update set
    status = case when mcp.mcp_storage_delete_jobs.status = 'completed' then 'completed' else 'pending' end,
    requested_by = excluded.requested_by,
    last_error = null,
    raw_payload = coalesce(mcp.mcp_storage_delete_jobs.raw_payload, '{}'::jsonb) || excluded.raw_payload,
    updated_at = now()
  returning * into v_job;

  update mcp.mcp_route_customers
     set active = false,
         raw_payload = coalesce(raw_payload, '{}'::jsonb) || jsonb_build_object(
           'hard_delete_job_id', v_job.id,
           'hard_delete_requested_context', coalesce(p_context, '{}'::jsonb)
         ),
         updated_at = now()
   where id = v_route_customer.id
   returning * into v_route_customer;

  update mcp.mcp_outlet_media
     set status = 'deleting',
         delete_requested_at = coalesce(delete_requested_at, now()),
         delete_attempt_count = delete_attempt_count + 1,
         last_delete_error = null,
         updated_at = now()
   where installation_id = p_installation_id
     and route_customer_id = v_route_customer.id
     and status <> 'deleted';

  select coalesce(jsonb_agg(to_jsonb(media) order by media.created_at), '[]'::jsonb)
    into v_media
    from mcp.mcp_outlet_media media
   where media.installation_id = p_installation_id
     and media.route_customer_id = v_route_customer.id
     and media.status <> 'deleted';

  return jsonb_build_object(
    'deleteJob', to_jsonb(v_job),
    'routeCustomer', to_jsonb(v_route_customer),
    'media', v_media
  );
end;
$function$;

-- Source: 20260719161000_add_outlet_media_delete_jobs.sql
create or replace function mcp.mcp_claim_route_media_delete(
  p_installation_id text,
  p_route_id text,
  p_context jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $function$
declare
  v_route mcp.mcp_routes%rowtype;
  v_job mcp.mcp_storage_delete_jobs%rowtype;
  v_media jsonb := '[]'::jsonb;
begin
  if nullif(btrim(coalesce(p_installation_id, '')), '') is null then
    raise exception 'installation_id_required' using errcode = '23514';
  end if;
  if nullif(btrim(coalesce(p_route_id, '')), '') is null then
    raise exception 'route_id_required' using errcode = '23514';
  end if;

  select * into v_route
    from mcp.mcp_routes
   where id = p_route_id
   for update;

  if not found then
    raise exception 'route_not_found' using errcode = '23503';
  end if;

  insert into mcp.mcp_storage_delete_jobs (
    id, installation_id, target_type, target_id, status, requested_by, raw_payload
  ) values (
    'msdj_' || replace(gen_random_uuid()::text, '-', ''),
    p_installation_id,
    'route',
    v_route.id,
    'pending',
    nullif(btrim(coalesce(p_context ->> 'actorId', '')), ''),
    jsonb_build_object('request_context', coalesce(p_context, '{}'::jsonb))
  )
  on conflict (installation_id, target_type, target_id)
  do update set
    status = case when mcp.mcp_storage_delete_jobs.status = 'completed' then 'completed' else 'pending' end,
    requested_by = excluded.requested_by,
    last_error = null,
    raw_payload = coalesce(mcp.mcp_storage_delete_jobs.raw_payload, '{}'::jsonb) || excluded.raw_payload,
    updated_at = now()
  returning * into v_job;

  update mcp.mcp_routes
     set active = false,
         raw_payload = coalesce(raw_payload, '{}'::jsonb) || jsonb_build_object(
           'hard_delete_job_id', v_job.id,
           'hard_delete_requested_context', coalesce(p_context, '{}'::jsonb)
         ),
         updated_at = now()
   where id = v_route.id
   returning * into v_route;

  update mcp.mcp_route_customers
     set active = false,
         updated_at = now()
   where route_id = v_route.id;

  update mcp.mcp_outlet_media media
     set status = 'deleting',
         delete_requested_at = coalesce(media.delete_requested_at, now()),
         delete_attempt_count = media.delete_attempt_count + 1,
         last_delete_error = null,
         updated_at = now()
   where media.installation_id = p_installation_id
     and media.route_customer_id in (
       select route_customer.id
         from mcp.mcp_route_customers route_customer
        where route_customer.route_id = v_route.id
     )
     and media.status <> 'deleted';

  select coalesce(jsonb_agg(to_jsonb(media) order by media.created_at), '[]'::jsonb)
    into v_media
    from mcp.mcp_outlet_media media
    join mcp.mcp_route_customers route_customer
      on route_customer.id = media.route_customer_id
   where media.installation_id = p_installation_id
     and route_customer.route_id = v_route.id
     and media.status <> 'deleted';

  return jsonb_build_object(
    'deleteJob', to_jsonb(v_job),
    'route', to_jsonb(v_route),
    'media', v_media
  );
end;
$function$;

-- Source: 20260719160000_add_outlet_media_deletion_lifecycle.sql
create or replace function mcp.mcp_claim_stale_outlet_media_delete(
  p_installation_id text,
  p_pending_before timestamptz,
  p_retry_before timestamptz,
  p_limit integer default 50,
  p_context jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $function$
declare
  v_media jsonb := '[]'::jsonb;
  v_limit integer := greatest(1, least(coalesce(p_limit, 50), 200));
begin
  with candidates as (
    select id
      from mcp.mcp_outlet_media
     where installation_id = p_installation_id
       and (
         (status in ('pending', 'failed') and created_at < p_pending_before)
         or
         (status in ('deleting', 'delete_failed') and updated_at < p_retry_before)
       )
     order by created_at
     for update skip locked
     limit v_limit
  ), claimed as (
    update mcp.mcp_outlet_media media
       set status = 'deleting',
           delete_requested_at = coalesce(media.delete_requested_at, now()),
           delete_attempt_count = media.delete_attempt_count + 1,
           last_delete_error = null,
           raw_payload = coalesce(media.raw_payload, '{}'::jsonb) || jsonb_build_object(
             'cleanup_claim_context', coalesce(p_context, '{}'::jsonb)
           ),
           updated_at = now()
      from candidates
     where media.id = candidates.id
     returning media.*
  )
  select coalesce(jsonb_agg(to_jsonb(claimed) order by claimed.created_at), '[]'::jsonb)
    into v_media
    from claimed;

  return v_media;
end;
$function$;

-- Source: 20260719162000_reclaim_outlet_media_delete_jobs.sql
create or replace function mcp.mcp_claim_ready_storage_delete_jobs(
  p_installation_id text,
  p_retry_before timestamptz,
  p_limit integer default 20,
  p_context jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $function$
declare
  v_jobs jsonb := '[]'::jsonb;
  v_limit integer := greatest(1, least(coalesce(p_limit, 20), 100));
begin
  if nullif(btrim(coalesce(p_installation_id, '')), '') is null then
    raise exception 'installation_id_required' using errcode = '23514';
  end if;
  if p_retry_before is null then
    raise exception 'retry_before_required' using errcode = '23514';
  end if;

  with candidates as (
    select job.id
      from mcp.mcp_storage_delete_jobs job
     where job.installation_id = p_installation_id
       and (
         job.status in ('pending', 'failed')
         or (job.status = 'finalizing' and job.updated_at < p_retry_before)
       )
       and (
         (
           job.target_type = 'route_customer'
           and not exists (
             select 1
               from mcp.mcp_outlet_media media
              where media.installation_id = job.installation_id
                and media.route_customer_id = job.target_id
                and media.status <> 'deleted'
           )
         )
         or
         (
           job.target_type = 'route'
           and not exists (
             select 1
               from mcp.mcp_outlet_media media
               join mcp.mcp_route_customers route_customer
                 on route_customer.id = media.route_customer_id
              where media.installation_id = job.installation_id
                and route_customer.route_id = job.target_id
                and media.status <> 'deleted'
           )
         )
       )
     order by job.requested_at
     for update skip locked
     limit v_limit
  ), claimed as (
    update mcp.mcp_storage_delete_jobs job
       set status = 'finalizing',
           attempt_count = job.attempt_count + 1,
           last_error = null,
           raw_payload = coalesce(job.raw_payload, '{}'::jsonb) || jsonb_build_object(
             'finalize_claim_context', coalesce(p_context, '{}'::jsonb)
           ),
           updated_at = now()
      from candidates
     where job.id = candidates.id
     returning job.*
  )
  select coalesce(jsonb_agg(to_jsonb(claimed) order by claimed.requested_at), '[]'::jsonb)
    into v_jobs
    from claimed;

  return v_jobs;
end;
$function$;

-- Source: 20260719161000_add_outlet_media_delete_jobs.sql
create or replace function mcp.mcp_finish_storage_delete_job(
  p_installation_id text,
  p_job_id text,
  p_succeeded boolean,
  p_error text default null,
  p_context jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $function$
declare
  v_job mcp.mcp_storage_delete_jobs%rowtype;
begin
  if nullif(btrim(coalesce(p_installation_id, '')), '') is null then
    raise exception 'installation_id_required' using errcode = '23514';
  end if;
  if nullif(btrim(coalesce(p_job_id, '')), '') is null then
    raise exception 'delete_job_id_required' using errcode = '23514';
  end if;

  select * into v_job
    from mcp.mcp_storage_delete_jobs
   where installation_id = p_installation_id
     and id = p_job_id
   for update;

  if not found then
    raise exception 'storage_delete_job_not_found' using errcode = '23503';
  end if;

  update mcp.mcp_storage_delete_jobs
     set status = case when coalesce(p_succeeded, false) then 'completed' else 'failed' end,
         completed_at = case when coalesce(p_succeeded, false) then now() else null end,
         last_error = case
           when coalesce(p_succeeded, false) then null
           else left(coalesce(nullif(btrim(p_error), ''), 'storage_parent_delete_failed'), 500)
         end,
         raw_payload = coalesce(raw_payload, '{}'::jsonb) || jsonb_build_object(
           'finish_context', coalesce(p_context, '{}'::jsonb)
         ),
         updated_at = now()
   where id = v_job.id
   returning * into v_job;

  return to_jsonb(v_job);
end;
$function$;

-- Source: 20260705_product_filter_type_normalization.sql
create or replace function mcp.mcp_get_product_variants(p_product_id text)
returns jsonb
language plpgsql
stable security definer
set search_path = public
as $$
declare
  v_product_id text := btrim(coalesce(p_product_id, ''));
begin
  if v_product_id = '' then return '[]'::jsonb; end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('productId', p.id, 'variantId', v.id, 'name', p.name, 'brand', coalesce(nullif(p.brand_name, ''), b.brand_name, p.brand_code), 'category', mcp.mcp_catalog_filter_type(p.name, p.category, p.source_key), 'rawCategory', p.category, 'sku', v.sku, 'variantName', v.variant_name, 'sizeLabel', v.size_label, 'sellUnit', v.sell_unit, 'packUnit', v.pack_unit, 'packQuantity', v.pack_quantity, 'price', v.base_price) order by v.variant_name, v.size_label, v.id)
    from mcp.product_variants v
    join mcp.products p on p.id = v.product_id
    left join mcp.product_brands b on b.brand_code = p.brand_code
    where p.id = v_product_id and p.status = 'active' and v.status = 'active'
  ), '[]'::jsonb);
end;
$$;

-- Source: 20260705_product_search_round_robin_filter_types.sql
create or replace function mcp.mcp_search_products(
  p_q text default null,
  p_category text default null,
  p_brand text default null,
  p_limit integer default 50
)
returns jsonb
language plpgsql
stable security definer
set search_path = public
as $$
declare
  v_q text := lower(btrim(coalesce(p_q, '')));
  v_category text := lower(btrim(coalesce(p_category, '')));
  v_brand text := lower(btrim(coalesce(p_brand, '')));
  v_limit integer := greatest(1, least(coalesce(p_limit, 50), 100));
begin
  return coalesce((
    with source as (
      select p.id product_id, v.id variant_id, p.name, coalesce(nullif(p.brand_name, ''), b.brand_name, p.brand_code) brand, p.category raw_category, mcp.mcp_catalog_filter_type(p.name, p.category, p.source_key) filter_type, v.sku, v.variant_name, v.size_label, v.sell_unit, v.pack_unit, v.pack_quantity, v.base_price
      from mcp.product_variants v
      join mcp.products p on p.id = v.product_id
      left join mcp.product_brands b on b.brand_code = p.brand_code
      where p.status = 'active' and v.status = 'active'
    ), matched as (
      select *, row_number() over (partition by filter_type order by name, variant_name, variant_id) type_rank
      from source
      where (v_category = '' or lower(filter_type) = v_category or lower(raw_category) = v_category or (v_category in ('nguyen lieu tra sua','nguyên liệu trà sữa','nl tra sua','nl trà sữa','tra sua','trà sữa') and lower(filter_type) in ('trà','sữa','siro','bột','topping','đường & ngọt','sinh tố','trái cây / mứt','kem / milk foam','phụ gia')))
        and (v_brand = '' or lower(brand) = v_brand)
        and (v_q = '' or lower(product_id) like '%' || v_q || '%' or lower(variant_id) like '%' || v_q || '%' or lower(name) like '%' || v_q || '%' or lower(coalesce(variant_name, '')) like '%' || v_q || '%' or lower(coalesce(sku, '')) like '%' || v_q || '%' or lower(coalesce(size_label, '')) like '%' || v_q || '%' or lower(raw_category) like '%' || v_q || '%' or lower(filter_type) like '%' || v_q || '%' or lower(coalesce(brand, '')) like '%' || v_q || '%')
    ), limited as (
      select * from matched order by type_rank, mcp.mcp_catalog_filter_order(filter_type), name, variant_name, variant_id limit v_limit
    )
    select jsonb_agg(jsonb_build_object('productId', product_id, 'variantId', variant_id, 'name', name, 'brand', brand, 'category', filter_type, 'rawCategory', raw_category, 'sku', sku, 'variantName', variant_name, 'sizeLabel', size_label, 'sellUnit', sell_unit, 'packUnit', pack_unit, 'packQuantity', pack_quantity, 'price', base_price) order by type_rank, mcp.mcp_catalog_filter_order(filter_type), name, variant_name, variant_id)
    from limited
  ), '[]'::jsonb);
end;
$$;

DROP TRIGGER IF EXISTS trg_mcp_session_customers_recalc_counters ON mcp.mcp_session_customers;
CREATE TRIGGER trg_mcp_session_customers_recalc_counters
AFTER INSERT OR UPDATE OF session_id, visit_status, order_id, test_id, report_id, followup_count OR DELETE
ON mcp.mcp_session_customers
FOR EACH ROW EXECUTE FUNCTION mcp.mcp_recalc_after_session_customer_change();

DROP TRIGGER IF EXISTS trg_mcp_visits_recalc_counters ON mcp.mcp_visits;
CREATE TRIGGER trg_mcp_visits_recalc_counters
AFTER INSERT OR UPDATE OF session_id, has_order, has_test, has_report, order_id, test_id, report_id OR DELETE
ON mcp.mcp_visits
FOR EACH ROW EXECUTE FUNCTION mcp.mcp_recalc_after_visit_change();

DROP TRIGGER IF EXISTS trg_mcp_followups_recalc_counters ON mcp.mcp_followups;
CREATE TRIGGER trg_mcp_followups_recalc_counters
AFTER INSERT OR UPDATE OF session_id, session_customer_id, status OR DELETE
ON mcp.mcp_followups
FOR EACH ROW EXECUTE FUNCTION mcp.mcp_recalc_after_followup_change();

